SELECT 'moj-all-verified-judgments-review-002-chunk-157' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3152076d-a012-5380-b7d6-20ca136d1568","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -وجود غرماء للمدعي مت إدخالهم يف الدعوى -مصادقة املدعى عليهم على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدول بإعسار املدعي -احلكم بثبوت إعسار املدعي وإلزام املدعى عليهم بإنظاره","document_number":"34165422","case_number":"33501808","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/17","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -وجود غرماء للمدعي مت إدخالهم يف الدعوى -مصادقة املدعى عليهم على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدول بإعسار املدعي -احلكم بثبوت إعسار املدعي وإلزام املدعى عليهم بإنظاره","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/17 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34165422 :‬‬\n                          ‫َر ْق ُم الدعوى‪33501808 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34240987‬تاريخه‪1434/06/14 :‬هـ‬\n\n\n       ‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬وجــود غرمــاء للمدعــي مت‬\n       ‫إدخالهــم يف الدعــوى‪ -‬مصادقــة املدعــى عليهــم علــى الدعــوى ســوى‬\n       ‫اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود العــدول بإعســار‬\n       ‫املدعــي‪ -‬احلكــم بثبــوت إعســار املدعــي وإلــزام املدعــى عليهــم بإنظــاره‬\n                                                                    ‫حلــن ميســرة ‪.‬‬\n\n\n\n\n       ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                              ‫ك َ‬     ‫قولــه تعالــى‪َ { :‬و ِإ ْن َ‬\n                                                                                        ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                     ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n       ‫ادعــى املدعــي وكالــة بــأن يف ذمــة موكلــه للمدعــى عليهــم مبالــغ ماليــة‬\n       ‫ا يف نــص القضية‬     ‫مبوجــب أحــكام صــدرت بحــق موكلــه مبينــة تفصيـ ً‬\n       ‫وأنــه ال يســتطيع ســداد هــذه األمــوال كونــه معســر ًا كمــا أن لــه غرمــاء‬\n       ‫كثــر غيــر املدعــى عليــه وطلــب إثبــات إعســار موكلــه‪ ،‬أجــاب املدعــى‬\n       ‫عليهــم بعــدم علمهــم عــن إعســار املدعــي كمــا أجــاب أحدهــم بعــدم‬\n       ‫املصادقــة علــى إعســاره‪ ،‬مت البحــث والتحــري عــن أمــوال املدعــي فلــم‬\n       ‫يظهــر مــال ميكــن الســداد منــه‪ ،‬أحضــر املدعــي وكالــة ثالثــة شــهود مت‬\n       ‫تعديلهــم شــرع ًا شــهدوا علــى صحــة الدعــوى‪ ،‬لألســباب املرصــودة يف‬\n\n‫‪195‬‬\n\f‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة‬  ‫ك َ‬    ‫{و ِإنْ َ‬\n                                                                                ‫نــص احلكــم ولقولــه تعالــى‪َ :‬‬\n‫ـون} صــدر احلكــم بثبــوت‬                            ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                                               ‫َكـ ْـم ِإنْ ُ‬\n                                                                                           ‫َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n‫إعســار املدعــي وإنظــاره إلــى حــن ميســره‪ ،‬قــرر املدعــى عليهــم القناعــة‬\n‫مــا عــدا واحــد فقــرر عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                                                          ‫باملنطقــة الشــرقية باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬    ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n‫مبحافظــة االحســاء وبنــاء علــى املعاملــة احملالــة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة االحســاء برقــم ‪ 33501808‬وتاريــخ‬\n‫‪1433/08/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331454520‬وتاريــخ‬\n‫‪1433/08/03‬ه ـ حضــر املدعــي ‪ ........‬الســعودي اجلنســية مبوجــب‬\n‫ا عــن ‪ ........‬الســعودي اجلنســية مبوجــب‬  ‫الســجل املدنــي رقــم ‪ ........‬وكيـ ً‬\n‫الســجل املدنــي رقــم ‪ ........‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل األحســاء الثانيــة برقــم ‪ .........‬وتاريــخ ‪1430/02/13‬ه ـ جلــد‬\n‫رقــم ‪ 2773‬والتــي تخولــه يف املخاصمــة واملدافعــة واملطالبــة وادعــى‬\n‫علــى احلاضــر معــه ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫ا يف حتريــر دعــواه إن بذمــة موكلــي للمدعــى عليــه‬           ‫رقــم ‪ ........‬قائ ـ ً‬\n‫مبلــغ قــدره مائــة وواحــد وســبعون ألف ـ ًا وخمســمائة ريــال هــي املتبقــي‬\n‫مــن املبلــغ الثابــت يف ذمــة موكلــي مــن الصــك الصــادر منكــم برقــم‬\n‫‪ 12/103‬وتاريــخ ‪1433/06/08‬ه ـ وقــد عجــز موكلــي مــن ســداد‬\n‫املبلــغ املتبقــي لكونــه معســر ال ميلــك مــن حطــام الدنيــا شــيئ ًا ال قليــل‬\n‫وال كثيــر أطلــب إثبــات إعســار موكلــي وإعطائــه صــك ًا يحتمــي‬\n\n                                                                                                                                    ‫‪196‬‬\n\f      ‫بــه مــن غرميــه هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫ا إن مــا ذكــره املدعــي وكالــة مــن أن لــي بذمــة موكلــه املبلــغ‬        ‫قائ ـ ً‬\n      ‫املذكــور صحيــح ومــا ذكــره املدعــي وكالــة مــن أن موكلــه معســر‬\n      ‫ـدي مــن إثبــات إعســار املدعــي‬‫ال مــال لــه فــا علــم لــي بذلــك وال مانــع لـ ّ‬\n      ‫أصالــة هــذه إجابتــي ثــم جــرى ســؤال املدعــي وكالــة هل لــدى موكلك‬\n      ‫غرمــاء غيــر املدعــى عليــه فقــال نعــم وأطلــب رفــع اجللســة جلــرد الغرمــاء‬\n      ‫وإفادتكــم بأســماء الغرمــاء ومبالغهــم وبنــاء علــى ذلــك ســيجري رفــع‬\n      ‫اجللســة لذلــك‪ .‬ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه وجــرى ســؤال املدعــي وكالــة هــل لــدى موكلــك غرمــاء غيــر‬\n      ‫املدعــى عليــه فقــال نعــم ففــي ذمــة موكلــي مبالــغ أخــرى لغرمــاء آخريــن‬\n      ‫غيــر املدعــى عليــه وتفصيلهــا كمــا يلــي ‪ -1‬مبلــغ قــدره «مائــة وســبعة‬\n      ‫وتســعون ألــف ريــال ثابتــة يف ذمــة موكلــي وذلــك مبوجــب قــرار مكتــب‬\n      ‫الفصــل يف منازعــات األوراق التجاريــة باألحســاء برقــم ‪.........‬وتاريــخ‬\n      ‫‪1433/08/05‬ه ـ ‪ -2‬مبلــغ قــدره مائــة ألــف ريــال ثابتــة يف ذمــة موكلــي‬\n      ‫وذلك بـ ــموجب قـ ــرار مكـ ــتب الفصـ ــل يف منازعات األوراق التــجاريـ ــة‬\n      ‫باألحســاء برقــم ‪ .........‬وتاريــخ ‪1433/08/05‬ه ـ ‪ -3‬مبلــغ قــدره ســبعة‬\n      ‫وثالثــون ألــف ريــال ثابتــة يف ذمــة موكلــي وذلــك مبوجــب قــرار مكتــب‬\n      ‫الفصــل يف منازعــات األوراق التجاريــة باألحســاء برقــم ‪.........‬وتاريــخ‬\n      ‫‪1433/07/13‬هـ ‪ -4‬مبلغ قدره ســبعة عشــر ألف ًا وخمســمائة ريال ثابتة‬\n      ‫يف ذمــة موكلــي وذلــك مبوجــب الصــك الصــادر مــن احملكمــة اجلزئيــة‬\n      ‫مبحافظــة األحســاء برقــم ‪ 33409414‬وتاريــخ ‪1433/09/12‬ه ـ وبنــاء‬\n      ‫علــى ذلــك ســيجري رفــع اجللســة إلبــاغ باقــي الغرمــاء باحلضــور ورفعــت‬\n      ‫اجللســة لذلــك‪ .‬ويف جلســة أخــرى حضــر مدعــي اإلعســار الســعودي‬\n\n\n‫‪197‬‬\n\f‫اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليهــم‬\n‫‪.........‬املذكــور هويتــه يف اجللســة املاضيــة كمــا حضــر ‪ ........‬الســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬الســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬الســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ........‬ولــم يحضــر املدخــل يف الدعــوى وقــد متــت‬\n‫الكتابــة لقســم احملضريــن باحملكمــة مــن أجــل إبالغــه مبوعــد هــذه‬\n‫اجللســة مبوجــب كتابــي رقــم‪ 332098081‬وتاريــخ ‪1433/11/23‬ه ـ‬\n‫ا إن مــا ذكــره املدعــي يف أن بذمتــه‬    ‫وبعــرض الدعــوى علــى أجــاب قائـ ً‬\n‫لــي مبلــغ قــدره مائــة وســبعة وتســعون ألــف ريــال صحيــح ومــا ذكــره مــن‬\n‫أنــه معســر ال مــال لــه فغيــر صحيــح فاملدعــي ليــس معســر وهــو ملــيء‬\n‫ولكنــه يخفــي أموالــه وقــد ذكــر لــي مــرات عــدة أنــه ال يضــع أموالــه يف‬\n‫البنــك بــل يخفيهــا يف منزلــه لــذا أرفــض إثبــات إعســار املدعــي وأطلــب‬\n‫إلزامــه بدفــع املبلــغ الــذي بذمتــه لــي هــذه إجابتــي وبعــرض الدعــوى‬\n‫علــى أجابــا إن مــا ذكــره املدعــي مــن أن بذمتــه لنــا املبلغــن املذكوريــن‬\n‫يف الدعــوى صحيــح ومــا ذكــره مــن أنــه معســر ال مــال لــه فــا علــم‬\n‫لنــا بذلــك والــذي يظهــر لنــا أنــه ال مــال عنــده هــذه إجابتنــا وبســؤال‬\n‫املدعــي عــن ذلــك قــال ال صحــة ملــا ذكــره املدعــى عليــه وإن كان يعلــم‬\n‫لــي مــا ًال فيلزمــه بيانــه كمــا أنــه إن كان لديــه بينــة علــى أنــي ملــيء‬\n‫فليحضرهــا وبســؤال املدعــى عليــه عــن ذلــك قــال إننــي ال أعــرف مــا ًال‬\n‫ثابت ـ ًا أو منقــو ًال للمدعــي حتــى أقــوم بداللــة القضــاء عليــه كمــا أنــه‬\n‫ال بينــة لــي علــى أنــه ملــيء هكــذا قــرر فجــرى االطــاع علــى نتائــج‬\n‫البحــث والتحــري عــن أمــوال مدعــي اإلعســار املرفقــة باملعاملــة مــن‬\n‫رئيــس مجلــس هيئــة ســوق املاليــة الرئيــس التنفيــذي برقم‪.........‬وتاريــخ‬\n\n\n                                                                                     ‫‪198‬‬\n\f      ‫‪1433/07/13‬ه ـ ونصهــا «تبــن عــدم وجــود أي بيانــات اســتثمارية‬\n      ‫للمذكــور كمــا بتاريــخ ‪1433/06/29‬ه ـ «ومــن مديــر مــرور محافظــة‬\n      ‫األحســاء برقــم ‪ .........‬وتاريــخ ‪1433/06/22‬ه ـ ونصهــا» هــذا الشــخص‬\n      ‫ال ميتلــك أي ســيارة» ومــن مديــر جــوازات محافظــة األحســاء برقــم‬\n      ‫‪ .........‬وتاريــخ ‪1433/06/23‬ه ـ ونصهــا «ال يوجــد مكفولــن لصاحــب‬\n      ‫العمــل املوضــح رقــم بطاقتــه» ومــن مديــر فــرع وزارة التجــارة والصناعــة‬\n      ‫باألحســاء برقــم ‪.........‬وتاريــخ ‪1433/06/22‬ه ـ ونصهــا «نفيدكــم أنــه‬\n      ‫باالســتعالم عــن طريــق احلاســب اآللــي اتضــح أن املذكــور ليــس لديــه‬\n      ‫ســجالت جتاريــة حتــى تاريخــه» ومــن مديــر فــرع وزارة الزراعــة بالهفــوف‬\n      ‫برقــم ‪ .........‬وتاريــخ ‪1433/06/25‬ه ـ ونصهــا نفيدكــم بأنــه مت البحــث‬\n      ‫يف ســجالت األقســام ذات العالقــة ولــم يعثــر علــى اســم املذكــور‬\n      ‫ضمنهــا» ومــن مؤسســة النقــد العربــي الســعودي برقــم ‪ .........‬وتاريــخ‬\n      ‫‪1433/08/24‬ه ـ ونصهــا بــأن املدعــو لــه عــدة حســابات األول لــدى‬\n      ‫بنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب مقفــل والرصيــد صفــر الثانــي لــدى‬\n      ‫البنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب مغلــق والرصيــد صفــر الثالــث لدى‬\n      ‫البنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب جــاري والرصيــد ‪ 295/70‬ريــال‬\n      ‫مديــن والرابــع لــدى بنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب حســاب حوالــه‬\n      ‫والرصيــد صفــر واخلامــس لــدى بنــك ‪ ........‬رقــم ونــوع احلســاب جــاري‬\n      ‫والرصيــد ‪36،2368‬ريــال مديــن والســادس لــدى البنــك ‪ ........‬رقــم‬\n      ‫‪ ........‬ونــوع احلســاب جــاري والرصيــد صفــر والســابع لــدى البنــك ‪........‬‬\n      ‫رقــم ‪ ........‬ونــوع احلســاب والرصيــد صفــر كمــا أن البنــك ‪ ........‬أفــاد‬\n      ‫بوجــود قــرض باســم املذكــور برصيــد ‪55860،86‬ريــال مديــن كمــا‬\n      ‫أفــاد البنــك بوجــود بطاقتــن ائتمانيتــن باســم املذكــور األولــى برصيــد‬\n\n\n‫‪199‬‬\n\f‫‪5254،03‬ريــال مديــن والثانيــة برصيــد ‪ 3223،63‬ريــال مديــن كمــا‬\n‫تلقــت املؤسســة إجابــات باقــي البنــوك ومفادهــا عــدم وجــود أيــة أرصــدة‬\n‫أو حســابات لديهــم أو لــدى فروعهــم العاملــة باململكــة» وبعــرض نتائــج‬\n‫البحــث والتحــري علــى املدعــى عليــه قــال إن املدعــي يخفــي أموالــه لــذا‬\n‫جــاءت نتائــج البحــث والتحــري عنــه ســلبية هكــذا قــرر فســألت املدعــي‬\n‫هــل لديــك بينــة علــى إعسـ ــارك فقـ ــال نـ ــعم وأطلــب رفـ ــع حســاب حوالــه‬\n‫والرصيــد صفــر واخلامــس لــدى بنــك ‪ ........‬رقــم ونــوع احلســاب جــاري‬\n‫والرصيــد ‪36،2368‬ريــال مديــن والســادس لــدى البنــك ‪ ........‬رقــم‬\n‫‪ ........‬ونــوع احلســاب جــاري والرصيــد صفــر والســابع لــدى البنــك ‪........‬‬\n‫رقــم ‪ ........‬ونــوع احلســاب والرصيــد صفــر كمــا أن البنــك ‪ ........‬أفــاد‬\n‫بوجــود قــرض باســم املذكــور برصيــد ‪55860،86‬ريــال مديــن كمــا‬\n‫أفــاد البنــك بوجــود بطاقتــن ائتمانيتــن باســم املذكــور األولــى برصيــد‬\n‫‪5254،03‬ريــال مديــن والثانيــة برصيــد ‪ 3223،63‬ريــال مديــن كمــا‬\n‫تلقــت املؤسســة إجابــات باقــي البنــوك ومفادهــا عــدم وجــود أيــة أرصــدة‬\n‫أو حســابات لديهــم أو لــدى فروعهــم العاملــة باململكــة» وبعــرض نتائــج‬\n‫البحــث والتحــري علــى املدعــى عليــه ‪ .........‬قــال إن املدعــي يخفــي‬\n‫أموالــه لــذا جــاءت نتائــج البحــث والتحــري عنــه ســلبية هكــذا قــرر‬\n‫فســألت املدعــي هــل لديــك بينــة علــى إعســارك فقــال نعــم وأطلــب رفــع‬\n                 ‫اجللســة إلحضارهــا فأجبتــه لطلبــه ورفعــت اجللســة لذلــك‪.‬‬\n‫ويف جلســة أخــرى حضــر املدعــي وكالــة كمــا حضــر املدعــى عليهــم‬\n‫‪ ......‬ولــم يحضــر املدعــى عليهمــا ووقــد ورد إلــى احملكمــة إفــادة‬\n‫أمــن محافظــة األحســاء برقــم ‪.........‬وتاريــخ ‪1434/01/10‬ه ـ ونصهــا‬\n‫نفيدكــم أنــه مت البحــث يف ســجالت احلاســب اآللــي فاتضــح بــأن‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫املواطــن غيــر ممنــوح أي أراضــي حتــى تاريخــه « ثــم ســألت املدعــي‬\n      ‫وكالــة هــل أحضــرت بينتــك التــي وعــدت بهــا يف اجللســة املاضيــة فقــال‬\n      ‫نعــم فأحضــر للشــهادة ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ........‬وقــال إننــي مــن مواليــد عــام ‪1396‬ه ـ وأســكن يف حــي ‪.........‬‬\n      ‫وأعمــل يف شــركة ‪ ........‬ولــي صلــة قرابــة باملدعــي فأنــا زوج أختــه كمــا‬\n      ‫أحضــر للشــهادة ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬وقــال إننــي مــن مواليــد عــام ‪1391‬ه ـ وأســكن يف حــي ‪.........‬‬\n      ‫باملبــرز وأعمــل يف ‪ ........‬ويوجــد بينــي وبــن مدعــي اإلعســار صلــة قرابــة‬\n      ‫ا إننــي أعــرف‬   ‫فأنــا زوج خالتــه وشــهد كل واحــد منهمــا منفــرد ًا قائ ـ ً‬\n      ‫مدعــي اإلعســار متــام املعرفــة وهــو رجــل معســر ال ميلــك مــن حطــام الدنيــا‬\n      ‫شــيئ ًا ال قليــل وال كثيــر ال ثابــت وال منقــول هــذه شــهادتي ثــم ســألت‬\n      ‫املدعــي وكالــة هــل لديــك زيــادة بينــات علــى دعــواك فقــال نعــم وأطلــب‬\n      ‫رفــع اجللســة إلحضارهــا ثــم أضــاف املدعــى عليهمــا قائلــن لقــد تبــن لنــا‬\n      ‫وجــود ســيارات لــدى مدعــي اإلعســار محجــوزة لــدى جمركــي البطحاء‬\n      ‫وســلوى ونطلــب ســؤال املدعــي عنهــا والكتابــة للجمركــن لإلفــادة‬\n      ‫عــن ذلــك وبســؤال املدعــي وكالــة عــن ذلــك قــال ال صحــة ملــا ذكــره‬\n      ‫املدعــى عليهمــا مــن أن ملوكلــي ســيارات لــدى املنفذيــن املذكوريــن‬\n      ‫وبإمــكان احملكمــة الكتابــة للمنفذيــن وســؤالهما عن ذلــك وبناء على‬\n      ‫ذلــك ســيجري رفــع اجللســة إلحضــار املدعــي باقــي بيناتــه كمــا ســيتم‬\n      ‫الكتابــة ملنفــذي جمــرك البطحــاء وســلوى لإلفــادة عــن وجــود ســيارات‬\n      ‫محجــوزة لديهــم باســم مدعــي اإلعســار أم ال وكــم عددهــا وماهــي‬\n      ‫أنواعهــا إن وجــدت ورفعــت اجللســة لذلــك ‪.‬ويف جلســة أخــرى حضــر‬\n      ‫املدعــي وكالــة كمــا حضــر مــن املدعــى عليهــم ولــم يحضــر املدعــى‬\n\n\n‫‪201‬‬\n\f‫عليــه وقـ ــد ورد إلــى احملكمــة كتــاب مديــر عــام جمــرك ســلوى برقــم‬\n‫‪ 4/689‬وتاريــخ ‪1434/02/17‬ه ـ فوجــدت نصــه بعــد املقدمــة « إشــارة‬\n‫إلــى خطــاب فضيلتكــم رقــم ‪ 34/281043‬وتاريــخ ‪1434/02/03‬ه ـ‬\n‫بشــأن االستفســار إن كان هنــاك ســيارات محجــوزة لــدى منفــذ‬\n‫ســلوى تخــص املدعــو ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬أود اإلفــادة أنــه بالرجــوع إلــى القســم املختــص باجلمــرك لــم‬\n‫يتبــن وجــود ســيارات محجــوزة لدينــا للمذكــور أعــاه» أ‪.‬ه ـ كمــا ورد‬\n‫إلــى احملكمــة كتــاب مديــر عــام جمــرك البطحــاء برقــم ‪11/1966‬‬\n‫وتاريــخ ‪1434/02/28‬ه ـ فوجدتــه يتضمــن» إشــارة إلــى خطابكــم‬\n‫رقــم ‪ 34/281090‬وتاريــخ ‪ 1434/02/05‬املتضمــن طلبكــم اإلفــادة‬\n‫عــن ســيارات محجــوزة لدينــا والعائــدة للمواطــن عليــه نفيدكــم بأنــه‬\n‫باســتعالم عــن معلومــات املذكــور تبــن أن ال يوجــد أي ســجالت تفيــد‬\n‫عــن املذكــور» أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليهــم أجابــوا قائلــن‬\n‫نكتفــي مبــا جــاء يف إفــادة اجلمركــن ثــم ســألت املدعــي وكالــة هــل‬\n‫أحضــرت شــاهد ًا ثالثـ ًا علــى دعــواك فقــال نعــم فأحضــر للشــهادة ‪........‬‬\n‫الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وقــال إننــي مــن‬\n‫مواليــد عــام ‪1372‬ه ـ وأســكن يف حــي ‪ .........‬باملبــرز وأنــا متقاعــد مــن‬\n‫شــركة ‪ ........‬واملدعــي مــن أبنــاء عمــي وأشــهد هلل تعالــى بأننــي أعــرف‬\n‫مدعــي اإلعســار متــام املعرفــة وهــو رجــل معســر ال ميلــك مــن حطــام الدنيــا‬\n‫شــيئ ًا ال قليــل وال كثيــر ال ثابــت وال منقــول واهلل علــى مــا أقــول شــهيد‬\n‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليهــم قالــوا إننــا ال نرغــب‬\n‫يف مناقشــة الشــاهد وال نقــدح يف عدالتــه فجــرى تعديــل الشــهود مــن‬\n‫قبــل ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪................‬‬\n\n\n                                                                                      ‫‪202‬‬\n\f      ‫و‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬فبعــد‬\n      ‫ســماع الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة طلــب إثبــات إعســار‬\n      ‫موكلــه وقــد أنكــر املدعــى عليــه ذلــك بينمــا صــادق املدعــى عليــه علــى‬\n      ‫أن املدعــي أصالــة ال مــال عنــده وقــد ظهــر مــن نتائــج البحــث والتحــري‬\n      ‫وشــهادة الشــهود املعدلــن عــدم وجــود مــال للمدعــي وقــد أكــد الشــهود‬\n      ‫إعســار املدعــي أصالــة ولقولــه تعالــى (وإن كان ذو ُعســر ٍة َف َن ِظــر ٌة إلــى‬\n      ‫يســره) لــذا ثبــت لــدي إعســار وألزمــت املدعــى عليهــم إنظــاره إلــى‬       ‫َم َ‬\n      ‫ميســره وبـ ــذلك حكمــت ويعتبــر احلكــم يف حــق املدعــى عليــه حضوري ًا‬\n      ‫بينمــا يعتبــر احلكــم يف حــق املدعــى عليــه غيابي ـ ًا لعــدم ورود مــا يفيــد‬\n      ‫إبالغــه بجلســات الدعــوى وهــو علــى حجتــه متــى حضــر وبعــرض‬\n      ‫احلكــم علــى املدعــى عليهــم احلاضــرون قــرر املدعــى عليهمــا قناعتهمــا‬\n      ‫باحلكــم بينمــا قــرر املدعــى عليــه عــدم قناعتــه باحلكــم وأن يرغــب يف‬\n      ‫رفعــه حملكمــة االســتئناف مــن غيــر تقــدمي الئحــة اعتراضيــة وســوف‬\n      ‫يجــري نظــم صــك وبعــث نســخة منــه للمدعــى عليهمــا مــن أجــل تقريــر‬\n      ‫القناعــة باحلكــم مــن عدمهــا وأن لهمــا مــدة ثالثــن يوم ـ ًا مــن التاريــخ‬\n      ‫احملــدد الســتالم نســخة احلكــم فــإذا لــم يقدمــا اعتراضهمــا خــال املــدة‬\n      ‫املقــررة فــإن حقهمــا يف طلــب االعتــراض علــى احلكــم يكــون ســاقط ًا‬\n      ‫وأمــا املدعــي فلكونــه حكــم لــه بجميــع طلبــه وبنــاء علــى املــادة ‪174‬‬\n      ‫مــن نظــام املرافعــات فــا حاجــة لعــرض احلكــم عليــه وللبيــان حــرر يف‬\n      ‫‪1434/03/08‬ه ـ ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                   ‫وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد انتهــت املــدة املقــررة العتــراض املدعــى عليــه‬\n      ‫وذلــك يــوم األربعــاء املوافــق ‪1434/05/15‬ه ـ كمــا انتهــت املــدة املقــررة‬\n\n\n‫‪203‬‬\n\f‫العتــراض املدعــى عليــه وذلــك يــوم االثنــن املوافــق ‪1424/05/27‬ه ـ‬\n‫ولــم يتقدمــا بالئحــة اعتراضيــة علــى احلكــم وبذلــك ســقط حقهمــا يف‬\n‫طلــب االعتــراض علــى احلكــم وســيتم بعــث املعاملــة ملقــام محكمــة‬\n‫االســتئناف لتدقيــق احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/29‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامة مبحافظة األحســاء برقــم ‪331454520‬‬\n‫وتاريــخ ‪1434/6/ 7‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪341418744‬‬\n‫وتاريــخ ‪1434/6/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلة القاضي‬\n‫باحملكمــة الشــيخ‪ /‬املسـ ّـجل برقــم ‪ 34165422‬وتاريــخ ‪1434/3/17‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬ضد‪/‬عــدة غرمــاء يف قضيــة حقوقيــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬\n                          ‫حــرر يف ‪1434/6/13‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                     ‫‪204‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":195,"source_page_end":204,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38627441252a57a8f0d01ca18905d38e2a62ac4b62ac09374f8309fa20f1feb6","normalized_text_hash":"f64561754b37001c1e13f70f1a723c47e9d08826456cb3d3aedab9840c773045","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p195-34165422"},{"id":"92c9068b-4a0b-54ce-bd25-7bde4e38b007","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي إثبات اإلعسار -عدم مصادقة املدعى عليه على إعسار املدعي -عجز املدعى عليه عن إحضار بينة بعدم إعسار املدعي -شهادة الشهود العدول على إعسار املدعي -بقاء مدعي اإلعسار مدة طويلة يف السجن قرينة على صحة دعواه -احلكم بثبوت اإلعسار لثبوت البينة .","document_number":"34176729","case_number":"33691927","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"إعسار -مطالبة املدعي إثبات اإلعسار -عدم مصادقة املدعى عليه على إعسار املدعي -عجز املدعى عليه عن إحضار بينة بعدم إعسار املدعي -شهادة الشهود العدول على إعسار املدعي -بقاء مدعي اإلعسار مدة طويلة يف السجن قرينة على صحة دعواه -احلكم بثبوت اإلعسار لثبوت البينة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/1 :‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176729 :‬‬\n                         ‫َر ْق ُم الدعوى‪33691927 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34230734‬تاريخه‪1434/4/5 :‬هـ‬\n\n\n      ‫إعســار‪ -‬مطالبــة املدعــي إثبــات اإلعســار‪ -‬عــدم مصادقــة املدعــى عليــه‬\n      ‫علــى إعســار املدعــي‪ -‬عجــز املدعــى عليــه عــن إحضــار بينــة بعــدم إعســار‬\n      ‫املدعــي‪ -‬شــهادة الشــهود العــدول علــى إعســار املدعــي‪ -‬بقــاء مدعــي‬\n      ‫اإلعســار مــدة طويلــة يف الســجن قرينــة علــى صحــة دعــواه‪ -‬احلكــم‬\n                                                 ‫بثبــوت اإلعســار لثبــوت البينــة ‪.‬‬\n\n\n\n\n      ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                             ‫ك َ‬   ‫‪ -1‬قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                           ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                        ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n      ‫‪-2‬حديــث قبيصــة بــن املخــارق وفيــه أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال ((حتــى يشــهد ثالثــة مــن ذوي احلجــا أن فالن ـ ًا أصابتــه فاقــة))‬\n\n\n\n\n      ‫ادعــى املدعــي أن يف ذمتــه للمدعــى عليــه مبلغ ـ ًا وقــدره ســتة وســبعون‬\n      ‫ألــف ريــال حيــث كان يعمــل لــدى املدعــى عليه يف محــل أعالف وحصل‬\n      ‫لديــه عجــز يف احملــل وقــد حكــم عليــه بتســليم هــذا املبلــغ مبوجــب‬\n      ‫حكــم صــادر مــن احملكمــة وقــرر املدعــي أنــه معســر وال يســتطيع‬\n      ‫الســداد وطلــب أثبــات إعســاره‪ ،‬أنكــر املدعــى عليــه إعســار املدعــي و‬\n      ‫قــرر أنــه ملــيء ولــم يســتطع إحضــار بينتــه علــى مالئــة املدعــي‪ ،‬أحضــر‬\n\n‫‪205‬‬\n\f‫املدعــي ثالثــة شــهود وجــرى تعديلهــم شــرع ًا شــهدوا علــى صحــة دعــواه‪،‬‬\n‫قــرر ناظــر القضيــة أنــه نظــر ًا الن املدعــي طــال ســجنه ولألســباب‬\n‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة‬ ‫ك َ‬   ‫{و ِإنْ َ‬   ‫املذكــورة ولقولــه تعالــى‪َ :‬‬\n‫ـون} فقــد ثبــت إعســار املدعــي‬                       ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                                                 ‫َكـ ْـم ِإنْ ُ‬\n                                                                                             ‫َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n‫وبــه حكم‪،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة‬\n              ‫االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف املســاعد برقــم ‪ 33691927‬وتاريــخ ‪1433/12/20‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331408177‬وتاريــخ ‪1433/07/27‬ه ـ ففــي‬\n‫يــوم االثنــن املوافق‪1433/12/20‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 00‬‬\n‫وفيهــا حضــر ‪ ........‬ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬كمــا‬\n‫حضــر حلضــوره ‪ ........‬ســعودي اجلنســية يحمــل ســجل مدنــي رقــم ‪........‬‬\n‫وأدعــى قائــا يف دعــواه لقــد كنــت أعمــل يف محــل أعــاف للمدعــى‬\n‫عليــه وقــد حصــل عجــز يف احملــل وهــو مبلــغ وقــدره ســته وســبعون ألــف‬\n‫ريــال وقــد حكــم علــي بذلــك مبوجــب صــك احلكــم الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 11/12/21‬يف ‪1430/2/15‬ه ـ وحيــث أنــي معســر‬\n‫ال أســتطيع ســداد املدعــى عليــه اطلــب إثبــات إعســاري هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكره املدعــي غير صحيح‬\n‫والصحيــح أن لديــه أمــوال منقولــة وهــي عبــارة عــن ثالث ســيارات األولى‬\n‫‪ ........‬والثانيــة والثالثــة ‪ ........‬وقــد حضــر عنــدي مجموعــة مــن أقاربــه‬\n                                                                                                                                      ‫‪206‬‬\n\f      ‫وقالــوا نريــد اعطــاءه مهلــة لكــي يقــوم بتســديد املبلــغ الــذي يف ذمتــه‬\n      ‫وأصلحــوا بينــي وبينــه علــى أن يعطينــي ثالثــة آالف ريــال شــهريا مت دفــع‬\n      ‫قســط واحــد وبعدهــا اختفــى ملــدة خمســة أشــهر تقريبــا وأنــا أعــرف بــأن‬\n      ‫لديــه أمــوال وهــو غيــر معســر هكــذا أجــاب وبعــرض ذلــك علــى املدعــي‬\n      ‫قــال مــا ذكــره املدعــى عليــه غيــر صحيــح والصحيــح مــا ذكرتــه ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه هــل لديــه بينــة علــى مــا ذكــره فقــال أطلــب‬\n      ‫مهلــة إلحضارهــا فأجيــب لطلبــه و يف جلســة أخــرى حضــر فيهــا املدعــي‬\n      ‫و املدعــى عليــه وبســؤال املدعــى عليــه عــن البينــة التــي وعــد بإحضارهــا‬\n      ‫يف اجللســة املاضيــة قــال لــم اســتطع إحضارهــا يف هــذه اجللســة واطلــب‬\n      ‫مهلــة أخــرى إلحضارهــا وبســؤاله عــن املهلــة التــي يرغــب فيهــا فقــال بأنه‬\n      ‫يرغــب يف إمهالــه أربعــة أشــهر هكــذا قــال وحيــث أنــه قــد جــرى إمهــال‬\n      ‫املدعــى عليــه مــدة كافيــة إلحضــار بينتــه وحيــث أن املدعــي ســجني‬\n      ‫وهــو متضــرر مــن كثــرة االســتمهاالت لــذا فقــد جــرى ســؤال املدعــي‬\n      ‫هــل لديــه بينــة علــى أنــه معســر فقــال نعــم واطلــب إمهالــي إلحضــار‬\n      ‫البينــة فأجيــب لطلبــه ويف جلســة أخــرى حضــر فيهــا املدعــي ولــم يحضــر‬\n      ‫املدعــى عليــه وبســؤال املدعــي عــن بينتــه قــال لقــد أحضــرت للشــهادة‬\n      ‫وأدائهــا كال مــن ‪ ........‬ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪........‬‬\n      ‫و‪ .........‬ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬ســوداني اجلنســية‬\n      ‫ا‬\n      ‫مبوجــب اإلقامــة رقــم ‪ ........‬ثــم شــهد كل واحــد منهــم مبفــرده قائ ـ ً‬\n      ‫أشــهد هلل تعالــى أن املدعــي هــذا احلاضــر معســر يف الوقــت احلاضــر‬\n      ‫وال نعلــم لــه أمــواال ثابتــة أو منقولــة هنــا يف الســعودية أو يف الســودان‬\n      ‫هكــذا شــهدوا وقــد جــرى تعديلهــم التعديــل الشــرعي مــن قبــل ‪........‬‬\n      ‫ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬و ‪ ........‬ســوداني اجلنســية‬\n\n\n‫‪207‬‬\n\f‫مبوجــب اإلقامــة رقــم ‪ ........‬ويف جلســة أخــرى حضــر فيهــا املدعــي ولــم‬\n‫يحضــر املدعــى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n‫املدعــى عليــه عجــز عــن إحضــار البينــة التــي تثبــت مــا دفــع بــه وإلحضــار‬\n‫املدعــي ثالثــة شــهود وقــد جــرى تعديلهــم شــرع ًا وقــد شــهدوا بإعســار‬\n‫املدعــي وحلديــث قبيصــة بــن احملــارق وفيــه أن النبــي صلــى اهلل عليــه‬\n‫وســلم قــال (حتــى يشــهد ثالثــة مــن ذوي احلجــا أن فالن ـ ًا أصابتــه فاقــه)‬\n‫وبنــاء علــى مــا جــاء يف أوراق املعاملــة وألن بقــاء املدعــي يف الســجن ال‬\n‫يكــون إال إذا ظهــر بأنــه قــادر علــى الســداد و مماطــل ألصحــاب احلــق‬\n‫ومبــا أنــه قــد بقــي يف الســجن مــدة طويلــة لذلــك كلــه فقــد ثبــت لــدي‬\n‫إعســار املدعــي وللمدعــى عليــه مطالبتــه باحلــق متــى مــا أصبــح املدعــي‬\n‫موســر ًا لقولــه تعالــى {وإن كان ذو عســرة فنظــرة إلــى ميســرة} جلميــع‬\n‫مــا تقــدم فقــد حكمــت بإعســار املدعــي وبعــرض احلكــم علــى املدعــي‬\n‫قــرر القناعــة بــه وســيتم بعــث نســخة مــن صــك احلكــم للمدعــى عليــه‬\n‫لتقــدمي مــا لديــه خــال ثالثــن يومـ ًا مــن تاريــخ اســتالمه لنســخة احلكــم‬\n‫وإذا لــم يتقــدم مبــا لديــه فــإن حقــه يف االعتــراض يســقط ويكتســب‬\n‫احلكــم الصفــة القطعيــة واهلل املوفــق وصلــى اهلل عليــه وســلم علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/3/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحد املوافــق ‪ 1434/06/25‬هـ‬\n‫افتتحت اجللســة يف متام الســاعة الثامنة وقد عادت املعاملة من محكمة‬\n‫االســتئناف بخطــاب رئيســها رقــم ‪ 331408177‬يف ‪1434/6/13‬ه ـ‬\n‫واملرفــق بــه قــرار التصديــق للدائــرة احلقوقيــة الرابعــة رقــم ‪34230734‬‬\n‫يف ‪1434/6/5‬ه ـ واملتضمــن وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بإثبــات إعســار املدعــي أ‪.‬ه ـ‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫لــذا فقــد أمــرت بالتهميــش علــى ســجله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/25‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ /‬القاضــي باحملكمــة العامة واملســجل بعــدد ‪34176729‬وتاريخ‬\n      ‫‪1434/4/1‬ه ـ املتضمــن دعــوى ‪ ........‬ســوداني اجلنســية ضــد ‪........‬‬\n      ‫واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم بإثبــات إعســار‬\n          ‫املدعــي‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪209‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":205,"source_page_end":209,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8f95b302cadbb753a0d9281e1449f23fc72edc68c772659d7fb0e2672578e43","normalized_text_hash":"33d4762431bd54f41fb8eef9bdc04bf1073f846c58548a82e20503cb122bf5bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p205-34176729"},{"id":"0633d599-4dcd-5f4b-acc6-8ccce86464df","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وإلزام املدعى عليه إنظار املدعي حلن ميسرة .","document_number":"34191872","case_number":"33428499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة األحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/4/20","year":"1434","subject":"إعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وإلزام املدعى عليه إنظار املدعي حلن ميسرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1432/4/20 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34191872 :‬‬\n                    ‫َر ْق ُم الدعوى‪33428499 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n     ‫‪/34239509‬ق‪/2‬أ تاريخه‪1434/6/13 :‬هـ‬\n\n\n ‫إعســار ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى ســوى اإلعســار‪ -‬التحري‬\n ‫وثبــوت اإلعســار ‪ -‬شــهادة الشــهود بإعســار املدعــي‪ -‬احلكــم بإثبــات‬\n           ‫اإلعســار وإلــزام املدعــى عليــه إنظــار املدعــي حلــن ميســرة ‪.‬‬\n\n\n\n\n ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                        ‫ك َ‬     ‫قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                  ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                               ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليــه وكالــة عــن إحــدى الشــركات بــأن‬\n ‫للشــركة موكلــة املدعــى عليــه يف ذمــة املدعــي مبلغ ـ ًا وقــدره واحــد‬\n ‫وثالثــون ألف ـ ًا ومائتــان وســبعة عشــر ريــا ًال مبوجــب قــرار صــادر مــن‬\n ‫وزارة التجــارة وكذلــك مبلغـ ًا وقــدره عشــرون ألفـ ًا ومائــة وأربعــون ريــا ًال‬\n ‫مبوجــب قــرار أيض ـ ًا مــن وزارة التجــارة «مكتــب الفصــل يف منازعــات‬\n ‫األوراق التجاريــة» وأن املدعــي ال يســتطيع الســداد لكونــه معســر ًا‬\n ‫وطالــب املدعــي إثبــات إعســاره‪ ،‬قــرر املدعــى عليــه وكالة أن الشــركة‬\n ‫تطالــب بحقهــا وال تعلــم عــن إعســار املدعــي ثــم قــرر املدعــى عليــه‬\n ‫وكالــة أن املبلــغ األول مت ســداده مــن فاعــل خيــر وبقــي املبلــغ الثانــي‪،‬‬\n ‫مت البحــث والتحــري عــن مــال املدعــي فلــم يظهــر مــا ًال ميكــن الســداد‬\n                                                                                                                                            ‫‪210‬‬\n\f      ‫منــه‪ ،‬أحضــر املدعــي ثالثــة شــهود يشــهدون علــى صحــة الدعــوى ومت‬\n      ‫تعديلهــم شــرعاً‪ ،‬لألســباب املرصــودة يف نــص احلكــم ولقولــه تعالــى‬\n       ‫َكـ ْـم ِإنْ‬\n                 ‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬ ‫ك َ‬   ‫{و ِإنْ َ‬   ‫َ‬\n      ‫ـون } صــدر احلكــم بثبــوت دعــوى اإلعســار وإلزام الشــركة‬                                               ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬ ‫ُ‬\n      ‫بإنظــار املدعــي إلــى ميســرة‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر‬\n                                   ‫قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫العامــة‬\n          ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫باألحســاء حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬كما حضر املدعى عليه وكالة ‪ ........‬الســعودي بالســجل املدني‬\n      ‫رقــم ‪...........‬بصفتــه وكيــا عــن ‪ ........‬الســعودي مبوجــب الســجل املدني‬\n      ‫رقــم ‪ ........‬بصفتــه رئيــس مجلــس املديريــن لشــركة ‪...........‬للســيارات‬\n      ‫احملــدودة مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال‬\n      ‫محافظــة جــدة برقــم ‪ ...........‬يف ‪1430/11/15‬ه ـ وقــال املدعــي يف‬\n      ‫حتريــر دعــواه إنــه صــدر علــي قــرار مــن وزارة التجــارة مــن مكتــب‬\n      ‫الفصــل يف منازعــات األوراق التجاريــة باألحســاء برقــم‪1431/236‬يف‬\n      ‫‪1431/7/15‬ه ـ بإلزامــي بدفــع واحــد وثالثــن ألــف ومئتــن وســبعة‬\n      ‫عشــر ريــاال للشــركة موكلــة املدعــى عليــه وليــس عنــدي مــا أســدد بــه‬\n      ‫هــذا املبلــغ مــن مــال منقــول أو ثابــت وأنــا معســر وأطلــب إثبــات إعســاري‬\n      ‫هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال إن الشــركة‬\n      ‫موكلتــي تطالــب املدعــي بحقهــا الثابــت وال تعلــم عــن حــال املدعــي‬\n      ‫شــيء كمــا أنــه صــدر عليــه قــرار آخــر مــن وزارة التجــارة بإلزامــه‬\n\n‫‪211‬‬\n\f‫بدفــع عشــرون ألــف ومائــة وأربعــون ريــاال ثابتــة مبوجــب قــرار مكتــب‬\n‫الفصــل يف منازاعــات األوراق التجاريــة رقــم ‪ 33/210‬يف ‪1433/7/6‬ه ـ‬\n‫وبعــرض ذلــك علــى املدعــي قــال صحيــح أنــه صــدر علــي القــرار الــذي‬\n‫ذكــره املدعــى عليــه وكالــة وال أســتطيع تســديد مــا يف ذمتي للشــركة‬\n‫وقــد جــرى منــا مخاطبــة اجلهــات املختصــة ووردنــا إفــادة مؤسســة النقــد‬\n‫العربــي الســعودي بالدمــام رقــم ‪...........‬يف ‪1433/8/19‬ه ـ املتضمــن‬\n‫عــدم وجــود أرصــدة يف حســابات املدعــي كمــا وردنــا إفــادة هيئــة‬\n‫ســوق املــال رقــم ‪...........‬يف ‪1433/7/19‬ه ـ بعــدم وجــود أســهم للمدعــي‬\n‫كمــا وردة إفــادة أمانــة األحســاء رقــم ‪...........‬يف ‪1433/7/19‬ه ـ بعــدم‬\n‫وجــود تصاريــح جتاريــة أو أمــاك عقاريــة للمدعــي ووردتنــا إفــادة‬\n‫غرفــة األحســاء رقــم ‪......................‬يف ‪2012/5/30‬م بعــدم وجــود‬\n‫ســجالت أو اشــتراك للمدعــي لدينــا وإفــادة الزراعــة كذلــك رقــم‬\n‫‪...........‬يف ‪1433/7/2‬ه ـ وإفــادة املــرور األحســاء رقــم ‪2/3/9107/7‬‬\n‫يف ‪1433/7/5‬ه ـ بعــدم وجــود ســيارات حتــت ملكيــة املدعــي ويف‬\n‫جلســة أخــرى قــال املدعــي إننــي قــد مت إطــاق ســراحي حيــث ســدد‬\n‫عنــي فاعــل خيــر هــذا املبلــغ الــذي يف ذمتــي وبعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة قــال إن الشــركة موكلتــي لــم تســتلم شــيء مــن املدعــي‬\n‫وال مــن فاعــل اخليــر الــذي ذكــر كمــا أنــه قــد صــدر علــى املدعــي‬\n‫حكــم آخــر بإلزامــه بدفــع عشــرين ألــف ومائــة وأربعــن ريــاال برقــم‬\n‫‪1433/210‬ه ـ يف ‪1433/7/6‬ه ـ صــادر مــن وزارة التجارة باألحســاء من‬\n‫مكتــب الفصــل يف املنازعــات التجاريــة والشــركة موكلتــي تطالــب‬\n‫املدعــي بهــذا املبلــغ كذلــك إضافــة إلــى املبلــغ الســابق وقــد مت إضافــة‬\n‫هــذه املعاملــة إلــى املعاملــة الســابقة وبعــرض ذلــك علــى املدعــي قــال إن‬\n\n\n                                                                                    ‫‪212‬‬\n\f      ‫القــرار الــذي ذكــر قــد صــدر علــي ولكنــي قــد ســددت للشــركة‬\n      ‫املدعــى عليهــا وســأحضر كشــف حســاب بهــا يف اجللســة القادمــة ويف‬\n      ‫جلســة أخــرى حضــر املدعــي كمــا حضــر املدعــى عليــه وكالــة ‪.......‬‬\n      ‫بعــد انتهــاء اجللســة وقدمــا اعتذارهمــا وقــال املدعــى عليــه وكالــة إن‬\n      ‫الشــركة موكلتــي اســتلمت مــن املدعــي الثابــت يف ذمتــه مــن قــرار‬\n      ‫وزارة التجــارة األول رقــم ‪...........‬يف ‪1431/7/15‬ه ـ والــذي ميثــل مبلــغ‬\n      ‫وقــدره واحــد وثالثــون ألــف ومائتــان وســبعة عشــر ريــاال مت دفعهــا مــن‬\n      ‫قبــل فاعــل خيــر وتبقــى يف ذمــة املدعــي للشــركة موكلتــي عشــرون‬\n      ‫ألــف ومائــة وأربعــون ريــاال وال زالــت الشــركة موكلتــي تطالــب‬\n      ‫بهــذا املبلــغ وقــال املدعــي إن هــذا املبلــغ ال زال يف ذمتــي وال أســتطيع‬\n      ‫تســديده وأطلــب إثبــات إعســاري وطلبــت مــن املدعــي البينــة علــى دعــواه‬\n      ‫و أحضــر كل مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬و‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ........‬و‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وشــهد كل واحــد‬\n      ‫منهــم مبفــرده قائــا أشــهد أن املدعــي معــروف لــي معرفــة تامــة و هــو‬\n      ‫معســر وليــس عنــده مــال ثابــت أو منقــول و ال يســتطيع ســداد مــا يف ذمتــه‬\n      ‫هــذا مــا أشــهد بــه و جــرى عــرض الشــهود و شــهادتهم علــى املدعــى عليــه‬\n      ‫وقــال إنــي ال أعرفهــم و ال مــا ذكــروا يف شــهادتهم و طلبــت مــن املدعــي‬\n      ‫تعديــل بينتــه و أحضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫شــهدا بعدالــة الشــهود وصالحيتهــم للشــهادة فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى و اإلجابــة و بعــد االســتظهار مــن حــال املدعــي و إفــادة اجلهــات‬\n      ‫املختصــة و بنــاء علــى شــهادة الشــهود املعدلــة شــرعا فقــد ثبــت لــدي‬\n\n\n‫‪213‬‬\n\f‫إعســار املدعــي مبــا عليــه مــن ديــن للشــركة املدعــى عليهــا و أنــه يلزمهــا‬\n‫إمهالــه إلــى ميســرة لقولــه تعالــى ( و إن كان ذو عســرة فنظــرة إلــى‬\n‫ميســرة ) اآليــة و بذلــك حكمــت و قــرر املدعــى عليــه وكالــة عــدم‬\n‫قناعتــه و طلــب االســتئناف و أفهمتــه املراجعــة يف يــوم الســبت املوافــق‬\n‫‪1434/04/20‬ه ـ الســتالم نســخة احلكــم و االعتــراض عليــه خــال‬\n‫ثالثــن يومــا و إال ســقط حقــه يف االعتــراض و أصبــح احلكــم قطعيــا‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1434/04/15‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/6/25‬ه ـ وقــد وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫الصــادر مــن الدائــرة احلقوقيــة الثانيــة برقــم ‪ / 34239509‬ق ‪ / 2‬أ‬\n‫وتاريــخ ‪1434/6/13‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪0‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم‪ 341125821‬وتاريــخ ‪ 1434/5/7‬ه ـ الــواردة مــن‬\n‫فضيلة رئيس احملكمة العامة مبحافظة األحســاء برقم ‪331203997‬‬\n‫وتاريــخ ‪1434/ 5/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 34191872‬وتاريــخ ‪1434/4/20‬هـ‬\n‫بشــأن دعــوى‪ /‬ضد‪/‬شــركة ‪ ...........‬للســيارات يف قضيــة حقوقيــة وقــد‬\n‫تضمــن الصــك حكــم فضيلــة القاضــي مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n\n\n                                                                                       ‫‪214‬‬\n\f      ‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                    ‫وآلــه وصحبــه وســلم حــرر يف‪1434/6/13‬ه ـ ‪.‬‬\n\n\n\n\n‫‪215‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":210,"source_page_end":215,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eb99da041abee0830bf3195694d1b56150df82cbcd24dca5f9bbd94ff399798a","normalized_text_hash":"50c67ea2eb755e9bad6682c21e86ae2bbd03c845d752eca294e6d570bd6b1030","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p210-34191872"},{"id":"fe9d5743-d439-52d3-b99c-f5a1d43a958f","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وعلى املدعى عليه إنظار املدعي حلن ميسرة .","document_number":"34229326","case_number":"33586013","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد بحائل بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وعلى املدعى عليه إنظار املدعي حلن ميسرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/4 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34229326 :‬‬\n                   ‫َر ْق ُم الدعوى‪33586013 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34239008‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬مصادقــة املدعــى عليــه علــى‬\n‫الدعــوى ســوى اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود‬\n‫بإعســار املدعــي‪ -‬احلكــم بإثبــات اإلعســار وعلــى املدعــى عليــه إنظــار‬\n                                                   ‫املدعــي حلــن ميســرة ‪.‬‬\n\n\n\n\n‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                       ‫ك َ‬     ‫قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                 ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                              ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n‫ادعــى املدعــي بــأن يف ذمتــه للمدعــى عليــه مبلغ ـ ًا وقــدره مائــة وأربعــون‬\n‫ألــف ريــال ثابتــة مبوجــب صــك شــرعي وأنــه ســجني بســبب هــذا املبلــغ‬\n‫منــذ ثمانيــة أشــهر وقــرر املدعــي أنــه فقيــر ومعســر وال يســتطيع ســداد‬\n‫املبلــغ الــذي يف ذمتــه وطلــب إثبــات إعســاره‪ ،‬رد املدعــى عليــه بعدم علمه‬\n‫بإعســار املدعــي‪ ،‬مت البحــث والتحــري عــن أمــوال مدعــي اإلعســار فلــم‬\n‫يظهــر لناظــر القضيــة وجــود مــال ميكــن منــه ســداد املبلــغ الــذي يف ذمــة‬\n‫املدعــي‪ ،‬أحضــر املدعــي ثالثــة شــهود جــرى تعديلهــم شــهدوا بصحــة‬\n‫ان‬\n‫ك َ‬        ‫{و ِإنْ َ‬\n                  ‫دعــواه‪ ،‬لألســباب املرصــودة يف نــص القضيــة ولقولــه تعالــى َ‬\n‫ك ْن ُتـ ْـم‬‫َكـ ْـم ِإنْ ُ‬\n                        ‫ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n\n                                                                                                                                           ‫‪216‬‬\n\f      ‫ـون } أثبــت ناظــر القضيــة إعســار املدعــي وأن علــى املدعــى عليــه‬\n                                                                            ‫َت ْعل َُمـ َ‬\n      ‫إنظــاره إلــى حــن ميســرة‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬مت تصديــق‬\n                                             ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد واهلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1433/9/24‬ه ـ‬\n      ‫الســاعة احلاديــة عشــر صباحــا لــدي أنــا ‪ ........‬رئيــس احملكمــة العامــة‬\n      ‫املســاعد بحائــل بنــاء علــى املعاملــة احملالــة لنــا برقــم ‪33586013‬‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 331742312‬وتاريــخ ‪1433/09/23‬ه ـ علــى‬\n      ‫خطــاب مديــر إدارة تنفيــذ األحــكام احلقوقيــة بحائــل رقــم ‪........‬يف‬\n      ‫‪1433/9/23‬ه ـ ألخــذ التوجيــه منــا بشــأن ســجن املدعــو ‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬اســتظهار ًا حلالــه حيــث‬\n      ‫قــرر عــدم اســتطاعته تنفيــذ احلكــم الصــادر منــا برقــم ‪33366623‬‬\n      ‫يف ‪1433/8/4‬ه ـ املتضمــن احلكــم عليــه بتســليم مبلــغ وقــدره مائــة‬\n      ‫وأربعــون ألــف ري ــ‪ 140.000‬ـ ــال وذلــك بحجــة أنــه معســر وحيــث األمــر‬\n      ‫مــا ذكــر وبنــاء علــى الفقــرة (‪ )11‬مــن املــادة (‪ )231‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة ومــا حلقهــا مــن تعديــل مبوجــب قــرار معالــي‬\n      ‫الوزيــر رقــم ‪ 3285‬يف ‪1428/3/15‬ه ـ واملعمــم علــى احملاكــم برقــم‬\n      ‫‪/13‬ت‪ 3093/‬يف ‪1423/4/7‬ه ـ فقــد قــررت ســجن املذكــور أربعــه‬\n      ‫أشــهر اســتظهار ًا حلالــه قبــل عرضــه علينــا وأقفلــت اجللســة يف متــام‬\n      ‫الســاعة احلاديــة عشــر والربــع مــن نفــس اليــوم وبــاهلل التوفيــق وصلــى‬\n                        ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/9/24‬ه ـ‬\n      ‫احلمــد واهلل وحــده وبعــد ففــي هــذا اليــوم االثنني املوافــق ‪1434/1/19‬هـ‬\n\n‫‪217‬‬\n\f‫الســاعة الواحــدة ظهــر ًا لــدي أنــا ‪ .........‬مســاعد رئيــس احملكمــة العامــة‬\n‫بحائــل بنــاء علــى املعاملــة املقيــدة بهــذه احملكمــة برقــم ‪ 3447185‬يف‬\n‫‪1434/1/6‬ه ـ علــى خطــاب مديــر إدارة تنفيــذ األحــكام احلقوقيــة‬\n‫بحائــل رقــم ‪........‬يف ‪1434/1/5‬ه ـ ألخــذ التوجيــه منــا بشــأن ســجن‬\n‫مدعــى اإلعســار املدعــو ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬اســتظهار ًا حلالــه حيــث قــرر عــدم اســتطاعته تنفيــذ احلكــم‬\n‫الصــادر منــا برقــم ‪ 33366623‬يف ‪1433/8/4‬ه ـ املتضمــن احلكم عليه‬\n‫بتســليم مبلــغ وقــدره مائــة وأربعــون ألــف ري ــ‪ 140.000‬ـ ــال وذلــك بحجــة‬\n‫أنــه معســر وحيــث األمــر مــا ذكــر وبنــاء علــى الفقــرة (‪ )11‬مــن املــادة‬\n‫(‪ )231‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ومــا حلقهــا‬\n‫مــن تعديــل مبوجــب قــرار معالــي الوزيــر رقــم ‪ 3285‬يف ‪1428/3/15‬ه ـ‬\n‫واملعمــم علــى احملاكــم برقــم ‪/13‬ت‪ 3093/‬يف ‪1423/4/7‬ه ـ فقــد‬\n‫قــررت متديــد ســجن املذكــور شــهر واحــد اســتظهار ًا حلالــه قبــل عرضــه‬\n‫علينــا وأقفلــت اجللســة يف متــام الســاعة الواحــدة والنصــف ظهــر ًا مــن‬\n‫نفــس اليــوم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                 ‫‪1434/1/19‬هــ‪.‬‬\n‫احلمد واهلل وحده وبعد ففي هذا اليوم األربعاء املوافق ‪1434/2/13‬هـ‬\n‫الســاعة التاســعة لــدي أنــا‪ ................‬مســاعد رئيــس احملكمــة العامــة‬\n‫بحائــل بنــاء علــى املعاملــة املقيــدة بهــذه احملكمــة برقــم ‪ 34355937‬يف‬\n‫‪1434/02/11‬ه ـ علــى خطــاب مديــر إدارة تنفيــذ األحــكام احلقوقيــة‬\n‫بحائــل رقــم ‪ ................‬يف ‪1434/02/11‬ه ـ ألخــذ التوجيــه منــا بشــأن‬\n‫ســجن مدعــى اإلعســار املدعــو ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬اســتظهار ًا حلالــه حيــث قــرر عــدم اســتطاعته تنفيــذ‬\n\n\n                                                                                      ‫‪218‬‬\n\f      ‫احلكــم الصــادر منــا برقــم ‪ 33366623‬يف ‪1433/8/4‬ه ـ املتضمــن‬\n      ‫احلكــم عليــه بتســليم مبلــغ وقــدره مائــة وأربعــون ألــف ري ــ‪ 140.000‬ـ ــال‬\n      ‫وذلــك بحجــة أنــه معســر وحيــث األمــر مــا ذكــر وبنــاء علــى الفقــرة‬\n      ‫(‪ )11‬مــن املــادة (‪ )231‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n      ‫التنفيذيــة ومــا حلقهــا مــن تعديــل مبوجــب قــرار معالــي الوزيــر رقــم‬\n      ‫‪ 3285‬يف ‪1428/3/15‬ه ـ واملعمــم علــى احملاكــم برقــم ‪/13‬ت‪3093/‬‬\n      ‫يف ‪1423/4/7‬ه ـ فقــد قــررت متديــد ســجن املذكــور شــهر واحــد‬\n      ‫اســتظهار ًا حلالــه قبــل عرضــه علينــا وأقفلــت اجللســة يف متــام الســاعة‬\n      ‫الواحــدة والنصــف ظهــر ًا مــن نفــس اليــوم وبــاهلل التوفيــق وصلــى اهلل‬\n                                ‫وســلم علــى نبينــا محمــد حــرر يف ‪1434/1/19‬هــ‪.‬‬\n      ‫احلمــد اهلل وحــده وبعــد ففــي هــذا اليوم االثنني املوافــق ‪1434/05/27‬هـ‬\n      ‫الســاعة العاشــرة صباح ـ ًا افتتحــت اجللســة الرابعــة وفيهــا حضــر ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى علــى‬\n      ‫احلاضــر معــه ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫ا يف حتريــر دعــواه أن لهــذا احلاضــر أمامكــم لــه بذمتــي مبلــغ‬         ‫قائ ـ ً‬\n      ‫وقــدرة مائــه وأربعــون ألــف ريــال حكــم لــه مبوجــب الصــك الصــادر‬\n      ‫منكــم برقــم ‪ 33366623‬يف ‪1433/8/4‬ه ـ وســجنت مبوجبــه ثمانيــة‬\n      ‫أشــهر وال أزال مســجون ًا حتــى تاريــخ اليــوم علــى ذمــه هــذا املبلــغ وأنــا‬\n      ‫رجــل فقيــر ومعســر وال اســتطيع الســداد اطلــب أثبــات إعســاري هــذه‬\n      ‫دعــواي وبســؤال املدعــي عليــه غــرمي املدعــي أجــاب قائ ـاً‪ :‬مــا ذكــره‬\n      ‫مدعــي اإلعســار مــن أن لــي بذمتــه مبلغ ـ ًا وقــدرة مائــة وأربعــون إلــف‬\n      ‫ريــال وحكــم لــي بالصــك املذكــور وســجن مبوجبــه املــدة املذكــورة‬\n      ‫فهــذا كلــه صحيــح ولكــن ال اعلــم عــن حالــة مدعــي اإلعســار شــيئا‬\n\n\n‫‪219‬‬\n\f‫هكــذا أجــاب وباالطــاع علــى أوراق املعاملــة وجــد بــن طياتهــا خطــاب‬\n‫نائــب محافــظ مؤسســة النقــد العربــي الســعودي رقــم‪ ........‬بتاريــخ‬\n‫‪1433/12/1‬ه ـ املتضمــن انــه مت الكشــف عــن أرصدة مدعي اإلعســار‬\n‫واتضــح انــه يوجــد لــه حســابني فقــط ‪-1‬يف مصــرف ‪ ........‬ورصيــده‬\n‫‪ 315.67‬ريــال وأفــاد املصــرف بوجــود ثالثــة عقــود متويــل باســم املذكــور‬\n‫‪ -2‬مجموعــة ‪ ........‬املاليــة أفــادت بوجــود حســاب جــاري باســم املذكــور‬\n‫أعــاه ورصيــده ‪ 6.37‬ريــال كمــا أفــادت املجموعــة بوجــود مديونيــة‬\n‫علــى املذكــور مبلــغ وقــدرة (‪ )45‬ريــال وهــو مرفــق باملعاملــة لفــه (‪)34‬‬\n‫وبطلــب البينــة مــن مدعــي اإلعســار علــى صحــة دعــواه أحضــر للشــهادة‬\n‫ال مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬  ‫وادائهــا ك ً‬\n‫‪ ........‬مــن مواليــد ‪1397‬ه ـ ليــس لــه صلــة قرابــة باملدعــي و‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬مــن مواليــد ‪1393‬ه ـ ليــس‬\n‫لــه صلــة قرابــة باملدعــي و‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬مــن مواليــد ‪1382‬ه ـ ليــس لــه صلــة قرابــة باملدعــي‬\n‫وباستشــهادهم شــهد كل واحــد منهــم مبفــردة قائـاً‪ :‬اشــهد اهلل تعالــى‬\n‫بــأن املدعــي رجــل فقيــر ومعســر وليــس لديــه مــا يســدد بــه دينــه ال ثابــت‬\n‫وال منقــول نعــرف ذلــك معرفــة تامــة هكــذا شــهدوا وبعــرض الشــهود‬\n‫ومــا جــاء يف شــهادتهم علــى املدعــي عليــه أجــاب قائ ـاً‪ :‬أمــا الشــهود‬\n‫فــا اقــدح بهــم بشــيء أمــا شــهادتهم فــاهلل أعلــم بصحتهــا هكــذا‬\n‫أجــاب كمــا حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n‫وشــهدا بعدالــة الشــهود وانهمــا يقبــان شــهادتهم لهمــا وعليهمــا فبنــاء‬\n‫علــى مــا ســلف مــن الدعــوى واإلجابــة وشــهادة الشــهود املعدلــن التعديــل‬\n\n\n                                                                                      ‫‪220‬‬\n\f      ‫الشــرعي وحيــث جــرى اســتظهار حــال املدعــي بالســجن والكشــف عــن‬\n      ‫أرصدتــه ولقولــه تعالــى ((وإن كان ذو عســرة فنظــرة إلــى ميســرة))‬\n      ‫لذلــك كلــه ثبــت لــدي أن املدعــي رجــل فقيــر ومعســر وأن علــى غرميــه‬\n      ‫املدعــى عليــه إنظــاره إلــى ميســره وبــه حكمــت وبعرضــه علــى الطرفــن‬\n      ‫قــرر املدعــي القناعــة باحلكــم أمــا املدعــى عليــه فقــرر عــدم القناعــة‬\n      ‫وطلــب رفعــة حملكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه‬\n      ‫لطلبــه وقــرر املدعــي عليــه أنــه لــن يوقــع علــى ضبــط القضيــة بحضــور‬\n      ‫شــهادة كاتبــة وأمــرت برفــع كامــل األوراق حملكمــة االســتئناف‬\n      ‫بحائــل لتدقيــق احلكــم ‪ -‬وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــره‬\n      ‫والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/27‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1434/6/24‬ه ـ‬\n      ‫الســاعة التاســعة والربــع صباح ـ ًا وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقصيــم بخطــاب فضيلــة رئيســها رقــم ‪3413469050‬‬\n      ‫يف ‪1434/6/18‬ه ـ املرفــق بــه قــرار أصحــاب ‪ 34239008‬يف‬\n      ‫‪1434/6/12‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة (( وبدراســة الصــك‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى مــا حكــم بــه‬\n      ‫فضيلتــه واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬قاضــي اســتئناف‪،........‬ختمه وتوقيعــه‪ .‬قاضــي اســتئناف‪،........‬‬\n      ‫ختمــه وتوقيعــه‪ .‬رئيــس الدائــرة‪ ،........‬ختمــه وتوقيعــه )) أ‪.‬ه ـ وعليــه فقــد‬\n      ‫رفعــت اجللســة يف متــام الســاعة التاســعة والنصــف صباحـ ًا يف نفــس اليــوم‬\n              ‫وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/6/24‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n\n\n‫‪221‬‬\n\f‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪ 341346905‬وتاريــخ ‪1434/6/4‬ه ـ واملقيــدة‬\n‫لدينــا بتاريــخ ‪1434/6/6‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34229326‬يف‬\n‫‪1434/6/4‬ه ـ الصــادر مــن فضيلــة رئيــس احملكمــة املســاعد اخلــاص‬\n‫بدعــوى ‪ ........‬ضــد ‪ ........‬بشــأن إثبــات إعســار علــى الصفــة املوضحــة يف‬\n‫الصــك واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيه وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى ماحكــم‬\n‫بــه فضيلتــه واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                       ‫وصحبــه‪.‬‬\n\n\n\n\n                                                                                    ‫‪222‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":216,"source_page_end":222,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c6050b57a953b7e1e527d38337296b0566e525cf6be4d068a32b174dc16eff1f","normalized_text_hash":"eb953ed08c6a316ebb51bb82e72f3427ac7c512853e86973afbb2ab688c2405a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p216-34229326"},{"id":"6467fdf4-ce76-5ba6-9e08-ab5340b692d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدل بإعسار املدعي -احلكم بثبوت اإلعسار .","document_number":"34231347","case_number":"33532463","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/5","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدل بإعسار املدعي -احلكم بثبوت اإلعسار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/5 :‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34231347 :‬‬\n                         ‫َر ْق ُم الدعوى‪33532463 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34276119‬تاريخه‪1434/7/23 :‬هـ‬\n\n\n      ‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬مصادقــة املدعــى عليــه علــى‬\n      ‫الدعــوى ســوى اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود‬\n                              ‫العــدل بإعســار املدعــي‪ -‬احلكــم بثبــوت اإلعســار ‪.‬‬\n\n\n\n\n      ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                            ‫ك َ‬    ‫‪ .1‬قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                          ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                       ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n      ‫‪ .2‬حديــث قبيصــة بــن املخــارق وفيــه أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال (( إن املســألة ال حتــل إال ألحــد ثالثــة ‪ -‬وذكــر منهــم ‪ -‬ورجــل‬\n      ‫أصابتــه فاقــة حتــى يقــول ثالثــة مــن ذوي احلجــا مــن قومــه لقــد‬\n                                   ‫أصابــت فــان فاقــة فحلــت لــه املســألة )) رواه مســلم‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه صــدر ضــده القــرار الصــادر مــن مكتــب الفصــل‬\n      ‫يف منازعــات األوراق التجاريــة مبكــة املكرمــة يتضمــن أن يســلم‬\n      ‫املدعــي للمدعــى عليــه مبلغــا وقــدره ثالثمائــة ألــف ريــال وقــرر املدعــي‬\n      ‫أنــه معســر وال يســتطيع الســداد وال عمــل لديــه وطلــب إثبــات إعســاره‪،‬‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي ســوى اإلعســار فقــرر عــدم‬\n      ‫علمــه بــه‪ ،‬أحضــر املدعــي ثالثــة شــهود مت تعديلهــم شــرعا يشــهدون‬\n\n‫‪223‬‬\n\f‫علــى صحــة الدعــوى‪ ،‬مت التحــري عــن مــال املدعــي فلــم يظهــر وجــود‬\n‫مــال ميكــن الســداد منــه‪ ،‬لألســباب املرصــودة يف نــص احلكــم ولقولــه‬\n‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر‬  ‫ك َ‬   ‫تعالــى { َو ِإنْ َ‬\n‫ـون } مت إثبــات إعســار املدعــي‪ ،‬قــرر املدعــى عليــه‬                                   ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                                                                                    ‫َكـ ْـم ِإنْ ُ‬\n                                                                                                                                ‫ل ُ‬\n                        ‫عــدم القناعــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم األحــد املوافــق ‪1434/05/05‬ه ـ لــدي‬\n‫أنــا ‪ ........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n‫املعاملــة احملالــة إلينــا بشــرح رئيــس احملكمــة برقــم ‪ 33532463‬وتاريــخ‬\n‫‪1433/08/18‬ه ـ املقيــد بأســاس هــذه احملكمــة برقــم ‪331495597‬‬\n‫وتاريــخ ‪1433/08/10‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة‬\n‫والنصــف صباحـ ًا وقــد جــرى الكتابــة للحقــوق املدنيــة مبوجــب خطابنــا‬\n‫رقــم ‪ 34839114‬وتاريــخ ‪1434/04/10‬ه ـ إلحضــار الســجني ويف هــذه‬\n‫اجللســة حضــر فيهــا ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ........‬وحضر حلضوره ‪ ........‬ســعودي بالســجل املدني رقم ‪ ........‬فادعى‬\n‫ا يف تقريــر دعــواه ‪ :‬لقــد صــدر ضــدي القــرار الصــادر مــن‬    ‫املدعــي قائـ ً‬\n‫مكتــب الفصــل يف منازعــات األوراق التجاريــة مبكــة املكرمــة برقــم‬\n‫‪ ........‬وتاريــخ ‪1432/12/26‬ه ـ للمدعــى عليــه وحيــث أننــي مطالــب‬\n‫للمدعــى عليــه مببلــغ وقــدره (‪ 300000‬ثالثمائــة ألف ريــال ) وحيث أنني‬\n‫معســر وليــس لــدي عمــل وال أملــك أيــة مــال ؛ لــذا أطلــب إثبــات إعســاري‬\n‫هــذه دعــواي ‪ ،‬وبعرضهــا علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره‬\n‫املدعــي يف دعــواه مــن ناحيــة صــدور القــرار ومقــدار املبلــغ فصحيــح ومــا‬\n\n                                                                                                                                      ‫‪224‬‬\n\f      ‫ذكــره مــن إعســاره باملبلــغ وأال عمــل لديــه وأنــه معســر وال ميلــك مــا ًال‬\n      ‫فــا أعلــم عنــه شــيئ ًا وأطلــب إلزامــه بســداد املبلــغ هكــذا أجــاب ثــم‬\n      ‫جــرى اطالعــي علــى القــرار الصــادر مــن مكتــب الفصــل يف منازعــات‬\n      ‫األوراق التجاريــة مبكــة املكرمــة رقــم ‪ ........‬وتاريــخ ‪1432/12/26‬ه ـ‬\n      ‫فــإذا هــو يتضمــن إلــزام املدعــي بســداد مبلــغ وقــدره (‪ 300000‬ثالثمائــة‬\n      ‫ألــف ريــال ) ثــم جــرى اطالعــي علــى إفــادة مؤسســة النقــد العربــي‬\n      ‫الســعودي مبكــة املكرمــة رقــم ‪ ........‬وتاريــخ ‪1433/11/16‬هـ فإذا هو‬\n      ‫يتضمــن لــدى املدعــي فقــط مبلــغ وقــدره (‪ 2958‬ألفــا وتســعمائة وثمــان‬\n      ‫وخمســون ريــال يف البنــك ‪ ) ........‬ثــم جــرى اطالعــي علــى إفــادة أمانــة‬\n      ‫العاصمــة املقدســة رقــم ‪........‬وتاريــخ ‪1433/09/13‬ه ـ فــإذا هــو يتضمــن‬\n      ‫عــدم وجــود رخــص محــات مســجلة باســمه ثــم ســألت املدعــى عليــه هــل‬\n      ‫يعــرف أعيــان مــال للمدعــى عليــه أو عقــار ؟ فأجــاب ‪ :‬ال أعلــم لــه شــيئ ًا‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب ‪ :‬بأننــي معســر وال‬\n      ‫أملــك شــيئ ًا ولــدي البينــة علــى ذلــك هكــذا أجــاب ولذا رفعت اجللســة ثم‬\n      ‫يف يــوم األربعــاء املوافــق ‪1434/05/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي واملدعــى عليــه املنــوه عنهمــا بعاليــه ‪ ،‬وبســؤال املدعــي عمــا‬\n      ‫وعــد بــه يف اجللســة املاضيــة مــن إحضــار البينــة علــى أنــه معســر أحضــرا‬\n      ‫للشــهادة كال مــن ‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n      ‫‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬و‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ،........‬وبســؤالهم‬\n      ‫عمــا لديهــم شــهد كل واحــد منهــم مبفــرده قائ ـاً‪ :‬إن املدعــي فقيــر ال‬\n      ‫مــال لــه وهــو محتــاج للمســاعدة ونحــن نعرفــه متــام املعرفــة وهــو عاجــز‬\n      ‫عــن ســداد مــا بذمتــه مــن مبالــغ هكــذا شــهدوا ‪ ،‬وبعــرض الشــهادة‬\n\n\n‫‪225‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":223,"source_page_end":225,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0331596b8046426e6243dd962617846d65e66810881c0febadda98f9ccfe60c6","normalized_text_hash":"e13e0d175c7815ea888a267e130d25259fbbc26018e6ebf4ccb7d226c4b82af4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p223-34231347"},{"id":"045730f8-29cb-5ba1-9a64-05bdd7961910","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة بإثبات إعسار -ثبوت الدين مبوجب سرقة -نصت التعليمات بعدم التساهل يف إثبات إعسار من كان دينه ناشئ عن سرقة ونحوه -احلكم بصرف النظر عن دعوى اإلعسار ألن الدين ثابت مبوجب سرقة واإللزام بدفع املبلغ .","document_number":"34250292","case_number":"33254934","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/25","year":"1434","subject":"إعسار -مطالبة بإثبات إعسار -ثبوت الدين مبوجب سرقة -نصت التعليمات بعدم التساهل يف إثبات إعسار من كان دينه ناشئ عن سرقة ونحوه -احلكم بصرف النظر عن دعوى اإلعسار ألن الدين ثابت مبوجب سرقة واإللزام بدفع املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34250292 :‬‬\n                         ‫َر ْق ُم الدعوى‪33254934 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34367196‬تاريخه‪1434/11/24 :‬هـ‬\n\n\n      ‫إعســار ‪ -‬مطالبــة بإثبــات إعســار ‪ -‬ثبــوت الديــن مبوجــب ســرقة ‪ -‬نصــت‬\n      ‫التعليمــات بعــدم التســاهل يف إثبــات إعســار مــن كان دينــه ناشــئ عــن‬\n      ‫ســرقة ونحــوه ‪ -‬احلكــم بصــرف النظــر عــن دعــوى اإلعســار ألن الديــن‬\n                                  ‫ثابــت مبوجــب ســرقة واإللــزام بدفــع املبلــغ ‪.‬‬\n\n\n\n\n      ‫تعميمــي معالــي وزيــر العــدل ذي الرقــم ‪/12/136‬ت والتاريــخ ‪1402/10/28‬ه ـ‬\n                                ‫وذي الرقــم ‪/13‬ت‪ 826/‬والتاريــخ ‪1416/07/04‬هــ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي (أجنبــي) يجيــد اللغــة العربية ضد ممثل الشــؤون الصحية‬\n      ‫بأنــه قــد صــدر عليــه حكــم شــرعي بإلزامــه بدفــع مبلــغ قيمــة أدويــة‬\n      ‫لــوزارة الصحــة ثــم ادعــى اإلعســار لــدى فضيلــة مصــدر احلكــم وحكــم‬\n      ‫بإثبــات إعســاره ونقــض احلكــم مــن محكمــة االســتئناف وليــس لديــه‬\n      ‫أمــوال وفقيــر ويطلــب إثبــات إعســاره هكــذا ادعــى‪ ،‬أجــاب املدعــى‬\n      ‫عليــه وكالــة بــأن مــا ذكــره املدعــي فهــو صحيــح ولكــن موكلتــه ال‬\n      ‫توافــق علــى إثبــات إعســاره وال تعلــم هــل لــه أمــوال أم ال وتطلــب احلكــم‬\n      ‫بــرد دعــواه‪ ،‬مت االطــاع علــى الصــك ويتضمــن أن مدعــي اإلعســار‬\n      ‫كان يعمــل فنــي تبريــد بــإدارة التمويــن الطبــي وقــد قــام بعــدة ســرقات‬\n‫‪229‬‬\n\f‫لكراتــن أدويــة وأنــه قــد ألــزم مببلــغ وقــدره (‪ ،)....‬وبنــاء علــى مــا‬\n‫جــاء يف تعميمــي معالــي وزيــر العــدل ذي الرقــم ‪/12/136‬ت والتاريــخ‬\n‫‪1402/10/28‬ه ـ وذي الرقــم ‪/13‬ت‪ 826/‬والتاريــخ ‪1416/07/04‬ه ـ‬\n‫واملتضمنــة عــدم التســاهل يف إثبــات اإلعســار إذا كان ســرقة‪ ،‬وملــا‬\n‫أن املبلــغ كبيــر جــدا‪ ،‬ملــا تقــدم لــم يثبــت أن املدعــي معسـ ّـر واحلكــم‬\n‫بصــرف النظــر عــن دعــواه يف اإلعســار وإلزامــه بدفــع املبلــغ املذكــور‬\n‫أعــاه للمدعــى عليهــا‪ ،‬اعتــرض املدعــي علــى احلكــم بالئحــة‪ ،‬صــدق‬\n          ‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪ 33254934‬وتاريــخ‬\n‫‪1433/04/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33529451‬وتاريــخ‬\n‫‪1433/03/20‬ه ـ ففــي يــوم األربعــاء ‪1434/01/28‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة التاســعة وفيهــا حضــر ‪ ....‬بنجالديشــي اجلنســية مســلم‬\n‫الديانــة مبوجــب رخصــة اإلقامــة رقــم ‪ ....‬كمــا حضــر حلضــوره ‪....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬بصفتــه ممثــل الشــؤون‬\n‫الصحيــة باخلطــاب رقــم ‪/47/110/101‬ج وتاريــخ ‪1434/01/27‬ه ـ‬\n‫الصــادر مــن مديــر الشــؤون الصحيــة مبحافظــة جــدة وادعــى األول‬\n‫قائــا وهــو يجيــد اللغــة العربيــة إنــه قــد صــدر علــي مــن فضيلــة الشــيخ‬\n‫‪ ............‬القاضــي بهــذه احملكمــة حكــم شــرعي بالصــك رقــم‬\n‫‪ 9/ 491/121‬وتاريــخ ‪1422/10/25‬ه ـ واملصــدق مــن الدائــرة احلقوقيــة‬\n\n                                                                                    ‫‪230‬‬\n\f      ‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة واملتضمــن بــأن‬\n      ‫أدفــع مبلغــا وقــدره ‪ 711562,02‬ســبعمائة وأحــد عشــر ألفــا وخمســمائة‬\n      ‫واثنــان وســتون ريــاال وهللتــان قيمــة أدويــة لــوزارة الصحــة ثــم ادعيــت‬\n      ‫اإلعســار لــدى فضيلــة ‪ ....‬وحكــم بإثبــات إعســاري بالصــك رقــم‬\n      ‫‪ 9358371226310154‬وتاريــخ ‪1431/11/18‬ه ـ ونقــض احلكــم‬\n      ‫مــن الدائــرة اجلزائيــة الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة بالقــرار رقــم ‪ 33122780‬وتاريــخ ‪1433/3/9‬ه ـ واملتضمــن‬\n      ‫نقــض احلكــم باألكثريــة وحتــال القضيــة لقاضــي آخــر للنظــر فيهــا‬\n      ‫مــن جديــد بعــد إنهــاء إجــراءات التهميــش علــى ضبطــه وســجله وأحيلــت‬\n      ‫لفضيلتكــم وإنــه ليــس لــدي أمــوال وإننــي فقيــر أطلــب إثبــات إعســاري‬\n      ‫هكــذا ادعــى وبســؤال املدعــى عليــه وكالــة اإلجابــة أجــاب قائــا مــا‬\n      ‫ذكــره املدعــي فهــو صحيــح ولكــن موكلتــي ال توافــق علــى إثبــات‬\n      ‫إعســاره وال تعلــم هــل لــه أمــوال أم ال وتطلــب احلكــم بــرد دعــواه‬\n      ‫هكــذا أجــاب والنتهــاء وقــت اجللســة رفعــت اجللســة واختتمــت اجللســة‬\n      ‫ثــم يف يــوم األربعــاء املوافق‪1434/02/13‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الثامنــة والنصــف وفيهــا حضــر املدعــي أصالــة ‪....‬املثبتــة هويتــه ســابقا‬\n      ‫لســماع دعــواه ‪....‬بشــأن دعــوى يف موضــوع حكــم منقــوض ‪ /‬غيــر‬\n      ‫مشــتركة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وقــد مت االطــاع علــى‬\n      ‫الصــك رقــم ‪ 9/491/121‬وتاريــخ ‪1422/01/25‬ه ـ واملصــادق عليــه‬\n      ‫مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة بالقــرار رقــم ‪ 1/2/314‬وتاريــخ ‪1423/03/16‬ه ـ ووجدتــه‬\n      ‫يتضمــن أن مدعــي اإلعســار كان يعمــل فنــي تبريــد بــإدارة التمويــن‬\n      ‫الطبــي وقــد قــام بعــدة ســرقات لكراتــن أدويــة وأنــه قــد ألــزم مببلــغ‬\n\n\n‫‪231‬‬\n\f‫وقــدره (‪ )711562,02‬ســبعمائة وأحــد عشــر ألفــا وخمســمائة واثنــان‬\n‫وســتون ريــاال وهللتــان كمــا قــد مت االطــاع على صك احلكــم املنقوض‬\n‫املذكــور يف دعــوى املدعــي فوجدتــه كمــا ذكــر ورفعت اجللســة للتأمل‬\n‫واختتمــت اجللســة ثــم يف يــوم األحــد ‪1434/06/11‬هـ افتتحت اجللســة يف‬\n‫الســاعة الثامنــة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــي أصالــة ‪....‬‬\n‫املثبتــة هويتــه ســابقا كمــا حضــر حلضــوره ‪....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪....‬بصفتــه ممثــل الشــؤون الصحيــة باخلطــاب رقــم‬\n‫‪/47/110/653‬ج وتاريــخ ‪1434/06/04‬ه ـ الصــادر مــن مديــر الشــؤون‬\n‫الصحيــة مبحافظــة جــدة ورفعــت اجللســة للتأمــل واختتمــت اجللســة ثــم‬\n‫يف يــوم األربعاء‪1434/06/21‬ه ـ افتتحــت اجللســة يف الســاعة الثامنــة‬\n‫والنصــف وفيهــا حضــر املدعــي أصالــة ‪....‬املثبتــة هويتــه ســابقا كمــا‬\n‫حضــر حلضــوره ممثــل املدعــى عليهــا ‪....‬املثبتــة هويتــه وتفويضــه ســابقا‬\n‫وقــد مت االطــاع علــى قــرار محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة رقــم ‪ 33122780‬وتاريــخ ‪1433/03/09‬ه ـ واملتضمــن نقــض‬\n‫احلكــم باألكثريــة وحتــال القضيــة لقــاض آخــر للنظــر فيهــا مــن‬\n‫جديــد بعــد إنهــاء إجــراءات التهميــش علــى ضبطــه وســجله ا‪.‬ه ـ فبنــاء‬\n‫علــى مــا تقــدم مــن دعــوى املدعــي واملتضمنــة طلبــه إثبــات إعســاره جهــة‬\n‫املدعــى عليهــا علــى مــا جــاء يف دعــواه وبنــاء علــى إجابــة املدعــى عليهــا‬\n‫واملتضمنــة عــدم املوافقــة علــى إثبــات إعســاره للمدعــي وبنــاء علــى مــا‬\n‫جــاء يف تعميمــي معالــي وزيــر العــدل ذي الرقــم ‪/12/136‬ت والتاريــخ‬\n‫‪1402/10/28‬ه ـ وذي الرقــم ‪/13‬ت‪ 826/‬والتاريــخ ‪1416/07/04‬ه ـ‬\n‫واملتضمنــة عــدم التســاهل يف إثبــات اإلعســار إذا كان ســرقة وملــا‬\n‫أن املبلــغ كبيــر جــدا فلــم يثبــت لــدي أن املدعــي معســرا وعليــه فقــد‬\n\n\n                                                                                      ‫‪232‬‬\n\f      ‫صرفــت النظــر عــن دعــواه يف اإلعســار وألزمتــه بدفــع املبلــغ املذكــور‬\n      ‫أعــاه للمدعــى عليهــا وبــه حكمــت وبإعــان احلكــم علــى املدعــي‬\n      ‫اعتــرض وطلــب التمييــز واســتعد بتقــدمي الئحــة اعتراضيــة فأفهــم بــأن‬\n      ‫عليــه مراجعــة احملكمــة يــوم األحــد ‪1434/06/25‬ه ـ الســتالم نســخة‬\n      ‫احلكــم وإذا فــات علــى ميعــاد االعتــراض ثالثــون يومــا ولــم يقــدم الئحته‬\n      ‫االعتراضيــة ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‪،‬‬\n      ‫واختتمــت اجللســة يف الســاعة التاســعة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/06/21‬ه ـ‬\n      ‫احلمــد هلل وحــده بعــد ففــي يــوم الثالثــاء ‪1434/06/27‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الثانيــة والنصــف وفيهــا حضــر املدعــي أصالــة ‪....‬‬\n      ‫املثبتــة هويتــه ســابقا واســتلم نســخة احلكــم وأفهــم بتعليمــات التمييــز‬\n      ‫كمــا يف اجللســة املاضيــة فتفهــم ذلــك‪ ،‬واختتمــت اجللســة ثــم يف يــوم‬\n      ‫األحــد ‪1434/07/23‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة عشــرة‬\n      ‫وفيهــا حضــر املدعــي أصالــة ‪....‬املثبتــة هويتــه ســابقا وقــدم الئحتــه‬\n      ‫االعتراضيــة املقيــدة يف احملكمــة برقــم ‪ 341775902‬وتاريــخ‬\n      ‫‪1434/07/23‬ه ـ واملكونــة مــن ورقــة واحــدة ورفعــت اجللســة لدراســتها‬\n      ‫واختتمــت اجللســة ثــم يف يــوم الســبت ‪1434/07/29‬ه ـ افتتحــت اجللســة‬\n      ‫يف الســاعة العاشــرة والربــع وقــد مت االطــاع علــى الالئحــة االعتراضيــة‬\n      ‫املقدمــة مــن املدعــي املذكــور رقــم قيدهــا وتاريخــه أعــاه ولــم أجــد بهــا‬\n      ‫مــا يؤثــر علــى مــا حكمــت بــه لــذا قــررت رفعهــا مــع كامــل املعاملــة‬\n      ‫والصــك وصــورة مصدقــة مــن الضبــط بعــد إحلــاق مــا اســتجد علــى‬\n      ‫الصــك والســجل حملكمــة االســتئناف‪ ،‬واختتمــت اجللســة يف الســاعة‬\n      ‫العاشــرة وخمــس وأربعــن دقيقــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n\n\n‫‪233‬‬\n\f   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/29‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬نحــن رئيس وقضاة‬\n‫الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة جــرى منــا االطــاع علــى الصــك رقــم ‪34250292‬وتاريــخ‬\n‫‪1434/6/25‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة‬\n‫العامــة مبحافظــة جــدة‪ ،‬املتضمــن دعــوى‪ ....‬بنجالديشــي اجلنســية‬\n‫ضــد‪ /‬الشــئون الصحيــة مبحافظــة جــدة‪ ،‬بشــأن طلــب أثبــات إعســار‪،‬‬\n‫احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم‪ ،‬واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪234‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":229,"source_page_end":234,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83f98f86444c3f7ee269f220261bedfa7beff3026985158881fcc17532fad96c","normalized_text_hash":"9b828fde56e78b2597e2f9a44a29031a2307bc4249fdb1889c772878236a0495","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p229-34250292"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3152076d-a012-5380-b7d6-20ca136d1568","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -وجود غرماء للمدعي مت إدخالهم يف الدعوى -مصادقة املدعى عليهم على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدول بإعسار املدعي -احلكم بثبوت إعسار املدعي وإلزام املدعى عليهم بإنظاره","document_number":"34165422","case_number":"33501808","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/17","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -وجود غرماء للمدعي مت إدخالهم يف الدعوى -مصادقة املدعى عليهم على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدول بإعسار املدعي -احلكم بثبوت إعسار املدعي وإلزام املدعى عليهم بإنظاره","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/17 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34165422 :‬‬\n                          ‫َر ْق ُم الدعوى‪33501808 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34240987‬تاريخه‪1434/06/14 :‬هـ‬\n\n\n       ‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬وجــود غرمــاء للمدعــي مت‬\n       ‫إدخالهــم يف الدعــوى‪ -‬مصادقــة املدعــى عليهــم علــى الدعــوى ســوى‬\n       ‫اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود العــدول بإعســار‬\n       ‫املدعــي‪ -‬احلكــم بثبــوت إعســار املدعــي وإلــزام املدعــى عليهــم بإنظــاره‬\n                                                                    ‫حلــن ميســرة ‪.‬‬\n\n\n\n\n       ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                              ‫ك َ‬     ‫قولــه تعالــى‪َ { :‬و ِإ ْن َ‬\n                                                                                        ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                     ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n       ‫ادعــى املدعــي وكالــة بــأن يف ذمــة موكلــه للمدعــى عليهــم مبالــغ ماليــة‬\n       ‫ا يف نــص القضية‬     ‫مبوجــب أحــكام صــدرت بحــق موكلــه مبينــة تفصيـ ً‬\n       ‫وأنــه ال يســتطيع ســداد هــذه األمــوال كونــه معســر ًا كمــا أن لــه غرمــاء‬\n       ‫كثــر غيــر املدعــى عليــه وطلــب إثبــات إعســار موكلــه‪ ،‬أجــاب املدعــى‬\n       ‫عليهــم بعــدم علمهــم عــن إعســار املدعــي كمــا أجــاب أحدهــم بعــدم‬\n       ‫املصادقــة علــى إعســاره‪ ،‬مت البحــث والتحــري عــن أمــوال املدعــي فلــم‬\n       ‫يظهــر مــال ميكــن الســداد منــه‪ ،‬أحضــر املدعــي وكالــة ثالثــة شــهود مت‬\n       ‫تعديلهــم شــرع ًا شــهدوا علــى صحــة الدعــوى‪ ،‬لألســباب املرصــودة يف‬\n\n‫‪195‬‬\n\f‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة‬  ‫ك َ‬    ‫{و ِإنْ َ‬\n                                                                                ‫نــص احلكــم ولقولــه تعالــى‪َ :‬‬\n‫ـون} صــدر احلكــم بثبــوت‬                            ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                                               ‫َكـ ْـم ِإنْ ُ‬\n                                                                                           ‫َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n‫إعســار املدعــي وإنظــاره إلــى حــن ميســره‪ ،‬قــرر املدعــى عليهــم القناعــة‬\n‫مــا عــدا واحــد فقــرر عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                                                          ‫باملنطقــة الشــرقية باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬    ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n‫مبحافظــة االحســاء وبنــاء علــى املعاملــة احملالــة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة االحســاء برقــم ‪ 33501808‬وتاريــخ‬\n‫‪1433/08/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331454520‬وتاريــخ‬\n‫‪1433/08/03‬ه ـ حضــر املدعــي ‪ ........‬الســعودي اجلنســية مبوجــب‬\n‫ا عــن ‪ ........‬الســعودي اجلنســية مبوجــب‬  ‫الســجل املدنــي رقــم ‪ ........‬وكيـ ً‬\n‫الســجل املدنــي رقــم ‪ ........‬وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل األحســاء الثانيــة برقــم ‪ .........‬وتاريــخ ‪1430/02/13‬ه ـ جلــد‬\n‫رقــم ‪ 2773‬والتــي تخولــه يف املخاصمــة واملدافعــة واملطالبــة وادعــى‬\n‫علــى احلاضــر معــه ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫ا يف حتريــر دعــواه إن بذمــة موكلــي للمدعــى عليــه‬           ‫رقــم ‪ ........‬قائ ـ ً‬\n‫مبلــغ قــدره مائــة وواحــد وســبعون ألف ـ ًا وخمســمائة ريــال هــي املتبقــي‬\n‫مــن املبلــغ الثابــت يف ذمــة موكلــي مــن الصــك الصــادر منكــم برقــم‬\n‫‪ 12/103‬وتاريــخ ‪1433/06/08‬ه ـ وقــد عجــز موكلــي مــن ســداد‬\n‫املبلــغ املتبقــي لكونــه معســر ال ميلــك مــن حطــام الدنيــا شــيئ ًا ال قليــل‬\n‫وال كثيــر أطلــب إثبــات إعســار موكلــي وإعطائــه صــك ًا يحتمــي‬\n\n                                                                                                                                    ‫‪196‬‬\n\f      ‫بــه مــن غرميــه هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫ا إن مــا ذكــره املدعــي وكالــة مــن أن لــي بذمــة موكلــه املبلــغ‬        ‫قائ ـ ً‬\n      ‫املذكــور صحيــح ومــا ذكــره املدعــي وكالــة مــن أن موكلــه معســر‬\n      ‫ـدي مــن إثبــات إعســار املدعــي‬‫ال مــال لــه فــا علــم لــي بذلــك وال مانــع لـ ّ‬\n      ‫أصالــة هــذه إجابتــي ثــم جــرى ســؤال املدعــي وكالــة هل لــدى موكلك‬\n      ‫غرمــاء غيــر املدعــى عليــه فقــال نعــم وأطلــب رفــع اجللســة جلــرد الغرمــاء‬\n      ‫وإفادتكــم بأســماء الغرمــاء ومبالغهــم وبنــاء علــى ذلــك ســيجري رفــع‬\n      ‫اجللســة لذلــك‪ .‬ويف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى‬\n      ‫عليــه وجــرى ســؤال املدعــي وكالــة هــل لــدى موكلــك غرمــاء غيــر‬\n      ‫املدعــى عليــه فقــال نعــم ففــي ذمــة موكلــي مبالــغ أخــرى لغرمــاء آخريــن‬\n      ‫غيــر املدعــى عليــه وتفصيلهــا كمــا يلــي ‪ -1‬مبلــغ قــدره «مائــة وســبعة‬\n      ‫وتســعون ألــف ريــال ثابتــة يف ذمــة موكلــي وذلــك مبوجــب قــرار مكتــب‬\n      ‫الفصــل يف منازعــات األوراق التجاريــة باألحســاء برقــم ‪.........‬وتاريــخ‬\n      ‫‪1433/08/05‬ه ـ ‪ -2‬مبلــغ قــدره مائــة ألــف ريــال ثابتــة يف ذمــة موكلــي‬\n      ‫وذلك بـ ــموجب قـ ــرار مكـ ــتب الفصـ ــل يف منازعات األوراق التــجاريـ ــة‬\n      ‫باألحســاء برقــم ‪ .........‬وتاريــخ ‪1433/08/05‬ه ـ ‪ -3‬مبلــغ قــدره ســبعة‬\n      ‫وثالثــون ألــف ريــال ثابتــة يف ذمــة موكلــي وذلــك مبوجــب قــرار مكتــب‬\n      ‫الفصــل يف منازعــات األوراق التجاريــة باألحســاء برقــم ‪.........‬وتاريــخ‬\n      ‫‪1433/07/13‬هـ ‪ -4‬مبلغ قدره ســبعة عشــر ألف ًا وخمســمائة ريال ثابتة‬\n      ‫يف ذمــة موكلــي وذلــك مبوجــب الصــك الصــادر مــن احملكمــة اجلزئيــة‬\n      ‫مبحافظــة األحســاء برقــم ‪ 33409414‬وتاريــخ ‪1433/09/12‬ه ـ وبنــاء‬\n      ‫علــى ذلــك ســيجري رفــع اجللســة إلبــاغ باقــي الغرمــاء باحلضــور ورفعــت‬\n      ‫اجللســة لذلــك‪ .‬ويف جلســة أخــرى حضــر مدعــي اإلعســار الســعودي‬\n\n\n‫‪197‬‬\n\f‫اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى عليهــم‬\n‫‪.........‬املذكــور هويتــه يف اجللســة املاضيــة كمــا حضــر ‪ ........‬الســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬الســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬الســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ........‬ولــم يحضــر املدخــل يف الدعــوى وقــد متــت‬\n‫الكتابــة لقســم احملضريــن باحملكمــة مــن أجــل إبالغــه مبوعــد هــذه‬\n‫اجللســة مبوجــب كتابــي رقــم‪ 332098081‬وتاريــخ ‪1433/11/23‬ه ـ‬\n‫ا إن مــا ذكــره املدعــي يف أن بذمتــه‬    ‫وبعــرض الدعــوى علــى أجــاب قائـ ً‬\n‫لــي مبلــغ قــدره مائــة وســبعة وتســعون ألــف ريــال صحيــح ومــا ذكــره مــن‬\n‫أنــه معســر ال مــال لــه فغيــر صحيــح فاملدعــي ليــس معســر وهــو ملــيء‬\n‫ولكنــه يخفــي أموالــه وقــد ذكــر لــي مــرات عــدة أنــه ال يضــع أموالــه يف‬\n‫البنــك بــل يخفيهــا يف منزلــه لــذا أرفــض إثبــات إعســار املدعــي وأطلــب‬\n‫إلزامــه بدفــع املبلــغ الــذي بذمتــه لــي هــذه إجابتــي وبعــرض الدعــوى‬\n‫علــى أجابــا إن مــا ذكــره املدعــي مــن أن بذمتــه لنــا املبلغــن املذكوريــن‬\n‫يف الدعــوى صحيــح ومــا ذكــره مــن أنــه معســر ال مــال لــه فــا علــم‬\n‫لنــا بذلــك والــذي يظهــر لنــا أنــه ال مــال عنــده هــذه إجابتنــا وبســؤال‬\n‫املدعــي عــن ذلــك قــال ال صحــة ملــا ذكــره املدعــى عليــه وإن كان يعلــم‬\n‫لــي مــا ًال فيلزمــه بيانــه كمــا أنــه إن كان لديــه بينــة علــى أنــي ملــيء‬\n‫فليحضرهــا وبســؤال املدعــى عليــه عــن ذلــك قــال إننــي ال أعــرف مــا ًال‬\n‫ثابت ـ ًا أو منقــو ًال للمدعــي حتــى أقــوم بداللــة القضــاء عليــه كمــا أنــه‬\n‫ال بينــة لــي علــى أنــه ملــيء هكــذا قــرر فجــرى االطــاع علــى نتائــج‬\n‫البحــث والتحــري عــن أمــوال مدعــي اإلعســار املرفقــة باملعاملــة مــن‬\n‫رئيــس مجلــس هيئــة ســوق املاليــة الرئيــس التنفيــذي برقم‪.........‬وتاريــخ‬\n\n\n                                                                                     ‫‪198‬‬\n\f      ‫‪1433/07/13‬ه ـ ونصهــا «تبــن عــدم وجــود أي بيانــات اســتثمارية‬\n      ‫للمذكــور كمــا بتاريــخ ‪1433/06/29‬ه ـ «ومــن مديــر مــرور محافظــة‬\n      ‫األحســاء برقــم ‪ .........‬وتاريــخ ‪1433/06/22‬ه ـ ونصهــا» هــذا الشــخص‬\n      ‫ال ميتلــك أي ســيارة» ومــن مديــر جــوازات محافظــة األحســاء برقــم‬\n      ‫‪ .........‬وتاريــخ ‪1433/06/23‬ه ـ ونصهــا «ال يوجــد مكفولــن لصاحــب‬\n      ‫العمــل املوضــح رقــم بطاقتــه» ومــن مديــر فــرع وزارة التجــارة والصناعــة‬\n      ‫باألحســاء برقــم ‪.........‬وتاريــخ ‪1433/06/22‬ه ـ ونصهــا «نفيدكــم أنــه‬\n      ‫باالســتعالم عــن طريــق احلاســب اآللــي اتضــح أن املذكــور ليــس لديــه‬\n      ‫ســجالت جتاريــة حتــى تاريخــه» ومــن مديــر فــرع وزارة الزراعــة بالهفــوف‬\n      ‫برقــم ‪ .........‬وتاريــخ ‪1433/06/25‬ه ـ ونصهــا نفيدكــم بأنــه مت البحــث‬\n      ‫يف ســجالت األقســام ذات العالقــة ولــم يعثــر علــى اســم املذكــور‬\n      ‫ضمنهــا» ومــن مؤسســة النقــد العربــي الســعودي برقــم ‪ .........‬وتاريــخ‬\n      ‫‪1433/08/24‬ه ـ ونصهــا بــأن املدعــو لــه عــدة حســابات األول لــدى‬\n      ‫بنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب مقفــل والرصيــد صفــر الثانــي لــدى‬\n      ‫البنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب مغلــق والرصيــد صفــر الثالــث لدى‬\n      ‫البنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب جــاري والرصيــد ‪ 295/70‬ريــال‬\n      ‫مديــن والرابــع لــدى بنــك ‪ ........‬رقــم ‪ ........‬ونــوع احلســاب حســاب حوالــه‬\n      ‫والرصيــد صفــر واخلامــس لــدى بنــك ‪ ........‬رقــم ونــوع احلســاب جــاري‬\n      ‫والرصيــد ‪36،2368‬ريــال مديــن والســادس لــدى البنــك ‪ ........‬رقــم‬\n      ‫‪ ........‬ونــوع احلســاب جــاري والرصيــد صفــر والســابع لــدى البنــك ‪........‬‬\n      ‫رقــم ‪ ........‬ونــوع احلســاب والرصيــد صفــر كمــا أن البنــك ‪ ........‬أفــاد‬\n      ‫بوجــود قــرض باســم املذكــور برصيــد ‪55860،86‬ريــال مديــن كمــا‬\n      ‫أفــاد البنــك بوجــود بطاقتــن ائتمانيتــن باســم املذكــور األولــى برصيــد‬\n\n\n‫‪199‬‬\n\f‫‪5254،03‬ريــال مديــن والثانيــة برصيــد ‪ 3223،63‬ريــال مديــن كمــا‬\n‫تلقــت املؤسســة إجابــات باقــي البنــوك ومفادهــا عــدم وجــود أيــة أرصــدة‬\n‫أو حســابات لديهــم أو لــدى فروعهــم العاملــة باململكــة» وبعــرض نتائــج‬\n‫البحــث والتحــري علــى املدعــى عليــه قــال إن املدعــي يخفــي أموالــه لــذا‬\n‫جــاءت نتائــج البحــث والتحــري عنــه ســلبية هكــذا قــرر فســألت املدعــي‬\n‫هــل لديــك بينــة علــى إعسـ ــارك فقـ ــال نـ ــعم وأطلــب رفـ ــع حســاب حوالــه‬\n‫والرصيــد صفــر واخلامــس لــدى بنــك ‪ ........‬رقــم ونــوع احلســاب جــاري‬\n‫والرصيــد ‪36،2368‬ريــال مديــن والســادس لــدى البنــك ‪ ........‬رقــم‬\n‫‪ ........‬ونــوع احلســاب جــاري والرصيــد صفــر والســابع لــدى البنــك ‪........‬‬\n‫رقــم ‪ ........‬ونــوع احلســاب والرصيــد صفــر كمــا أن البنــك ‪ ........‬أفــاد‬\n‫بوجــود قــرض باســم املذكــور برصيــد ‪55860،86‬ريــال مديــن كمــا‬\n‫أفــاد البنــك بوجــود بطاقتــن ائتمانيتــن باســم املذكــور األولــى برصيــد‬\n‫‪5254،03‬ريــال مديــن والثانيــة برصيــد ‪ 3223،63‬ريــال مديــن كمــا‬\n‫تلقــت املؤسســة إجابــات باقــي البنــوك ومفادهــا عــدم وجــود أيــة أرصــدة‬\n‫أو حســابات لديهــم أو لــدى فروعهــم العاملــة باململكــة» وبعــرض نتائــج‬\n‫البحــث والتحــري علــى املدعــى عليــه ‪ .........‬قــال إن املدعــي يخفــي‬\n‫أموالــه لــذا جــاءت نتائــج البحــث والتحــري عنــه ســلبية هكــذا قــرر‬\n‫فســألت املدعــي هــل لديــك بينــة علــى إعســارك فقــال نعــم وأطلــب رفــع‬\n                 ‫اجللســة إلحضارهــا فأجبتــه لطلبــه ورفعــت اجللســة لذلــك‪.‬‬\n‫ويف جلســة أخــرى حضــر املدعــي وكالــة كمــا حضــر املدعــى عليهــم‬\n‫‪ ......‬ولــم يحضــر املدعــى عليهمــا ووقــد ورد إلــى احملكمــة إفــادة‬\n‫أمــن محافظــة األحســاء برقــم ‪.........‬وتاريــخ ‪1434/01/10‬ه ـ ونصهــا‬\n‫نفيدكــم أنــه مت البحــث يف ســجالت احلاســب اآللــي فاتضــح بــأن‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫املواطــن غيــر ممنــوح أي أراضــي حتــى تاريخــه « ثــم ســألت املدعــي‬\n      ‫وكالــة هــل أحضــرت بينتــك التــي وعــدت بهــا يف اجللســة املاضيــة فقــال‬\n      ‫نعــم فأحضــر للشــهادة ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ........‬وقــال إننــي مــن مواليــد عــام ‪1396‬ه ـ وأســكن يف حــي ‪.........‬‬\n      ‫وأعمــل يف شــركة ‪ ........‬ولــي صلــة قرابــة باملدعــي فأنــا زوج أختــه كمــا‬\n      ‫أحضــر للشــهادة ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬وقــال إننــي مــن مواليــد عــام ‪1391‬ه ـ وأســكن يف حــي ‪.........‬‬\n      ‫باملبــرز وأعمــل يف ‪ ........‬ويوجــد بينــي وبــن مدعــي اإلعســار صلــة قرابــة‬\n      ‫ا إننــي أعــرف‬   ‫فأنــا زوج خالتــه وشــهد كل واحــد منهمــا منفــرد ًا قائ ـ ً‬\n      ‫مدعــي اإلعســار متــام املعرفــة وهــو رجــل معســر ال ميلــك مــن حطــام الدنيــا‬\n      ‫شــيئ ًا ال قليــل وال كثيــر ال ثابــت وال منقــول هــذه شــهادتي ثــم ســألت‬\n      ‫املدعــي وكالــة هــل لديــك زيــادة بينــات علــى دعــواك فقــال نعــم وأطلــب‬\n      ‫رفــع اجللســة إلحضارهــا ثــم أضــاف املدعــى عليهمــا قائلــن لقــد تبــن لنــا‬\n      ‫وجــود ســيارات لــدى مدعــي اإلعســار محجــوزة لــدى جمركــي البطحاء‬\n      ‫وســلوى ونطلــب ســؤال املدعــي عنهــا والكتابــة للجمركــن لإلفــادة‬\n      ‫عــن ذلــك وبســؤال املدعــي وكالــة عــن ذلــك قــال ال صحــة ملــا ذكــره‬\n      ‫املدعــى عليهمــا مــن أن ملوكلــي ســيارات لــدى املنفذيــن املذكوريــن‬\n      ‫وبإمــكان احملكمــة الكتابــة للمنفذيــن وســؤالهما عن ذلــك وبناء على‬\n      ‫ذلــك ســيجري رفــع اجللســة إلحضــار املدعــي باقــي بيناتــه كمــا ســيتم‬\n      ‫الكتابــة ملنفــذي جمــرك البطحــاء وســلوى لإلفــادة عــن وجــود ســيارات‬\n      ‫محجــوزة لديهــم باســم مدعــي اإلعســار أم ال وكــم عددهــا وماهــي‬\n      ‫أنواعهــا إن وجــدت ورفعــت اجللســة لذلــك ‪.‬ويف جلســة أخــرى حضــر‬\n      ‫املدعــي وكالــة كمــا حضــر مــن املدعــى عليهــم ولــم يحضــر املدعــى‬\n\n\n‫‪201‬‬\n\f‫عليــه وقـ ــد ورد إلــى احملكمــة كتــاب مديــر عــام جمــرك ســلوى برقــم‬\n‫‪ 4/689‬وتاريــخ ‪1434/02/17‬ه ـ فوجــدت نصــه بعــد املقدمــة « إشــارة‬\n‫إلــى خطــاب فضيلتكــم رقــم ‪ 34/281043‬وتاريــخ ‪1434/02/03‬ه ـ‬\n‫بشــأن االستفســار إن كان هنــاك ســيارات محجــوزة لــدى منفــذ‬\n‫ســلوى تخــص املدعــو ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬أود اإلفــادة أنــه بالرجــوع إلــى القســم املختــص باجلمــرك لــم‬\n‫يتبــن وجــود ســيارات محجــوزة لدينــا للمذكــور أعــاه» أ‪.‬ه ـ كمــا ورد‬\n‫إلــى احملكمــة كتــاب مديــر عــام جمــرك البطحــاء برقــم ‪11/1966‬‬\n‫وتاريــخ ‪1434/02/28‬ه ـ فوجدتــه يتضمــن» إشــارة إلــى خطابكــم‬\n‫رقــم ‪ 34/281090‬وتاريــخ ‪ 1434/02/05‬املتضمــن طلبكــم اإلفــادة‬\n‫عــن ســيارات محجــوزة لدينــا والعائــدة للمواطــن عليــه نفيدكــم بأنــه‬\n‫باســتعالم عــن معلومــات املذكــور تبــن أن ال يوجــد أي ســجالت تفيــد‬\n‫عــن املذكــور» أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليهــم أجابــوا قائلــن‬\n‫نكتفــي مبــا جــاء يف إفــادة اجلمركــن ثــم ســألت املدعــي وكالــة هــل‬\n‫أحضــرت شــاهد ًا ثالثـ ًا علــى دعــواك فقــال نعــم فأحضــر للشــهادة ‪........‬‬\n‫الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وقــال إننــي مــن‬\n‫مواليــد عــام ‪1372‬ه ـ وأســكن يف حــي ‪ .........‬باملبــرز وأنــا متقاعــد مــن‬\n‫شــركة ‪ ........‬واملدعــي مــن أبنــاء عمــي وأشــهد هلل تعالــى بأننــي أعــرف‬\n‫مدعــي اإلعســار متــام املعرفــة وهــو رجــل معســر ال ميلــك مــن حطــام الدنيــا‬\n‫شــيئ ًا ال قليــل وال كثيــر ال ثابــت وال منقــول واهلل علــى مــا أقــول شــهيد‬\n‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليهــم قالــوا إننــا ال نرغــب‬\n‫يف مناقشــة الشــاهد وال نقــدح يف عدالتــه فجــرى تعديــل الشــهود مــن‬\n‫قبــل ‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪................‬‬\n\n\n                                                                                      ‫‪202‬‬\n\f      ‫و‪ ........‬الســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬فبعــد‬\n      ‫ســماع الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة طلــب إثبــات إعســار‬\n      ‫موكلــه وقــد أنكــر املدعــى عليــه ذلــك بينمــا صــادق املدعــى عليــه علــى‬\n      ‫أن املدعــي أصالــة ال مــال عنــده وقــد ظهــر مــن نتائــج البحــث والتحــري‬\n      ‫وشــهادة الشــهود املعدلــن عــدم وجــود مــال للمدعــي وقــد أكــد الشــهود‬\n      ‫إعســار املدعــي أصالــة ولقولــه تعالــى (وإن كان ذو ُعســر ٍة َف َن ِظــر ٌة إلــى‬\n      ‫يســره) لــذا ثبــت لــدي إعســار وألزمــت املدعــى عليهــم إنظــاره إلــى‬       ‫َم َ‬\n      ‫ميســره وبـ ــذلك حكمــت ويعتبــر احلكــم يف حــق املدعــى عليــه حضوري ًا‬\n      ‫بينمــا يعتبــر احلكــم يف حــق املدعــى عليــه غيابي ـ ًا لعــدم ورود مــا يفيــد‬\n      ‫إبالغــه بجلســات الدعــوى وهــو علــى حجتــه متــى حضــر وبعــرض‬\n      ‫احلكــم علــى املدعــى عليهــم احلاضــرون قــرر املدعــى عليهمــا قناعتهمــا‬\n      ‫باحلكــم بينمــا قــرر املدعــى عليــه عــدم قناعتــه باحلكــم وأن يرغــب يف‬\n      ‫رفعــه حملكمــة االســتئناف مــن غيــر تقــدمي الئحــة اعتراضيــة وســوف‬\n      ‫يجــري نظــم صــك وبعــث نســخة منــه للمدعــى عليهمــا مــن أجــل تقريــر‬\n      ‫القناعــة باحلكــم مــن عدمهــا وأن لهمــا مــدة ثالثــن يوم ـ ًا مــن التاريــخ‬\n      ‫احملــدد الســتالم نســخة احلكــم فــإذا لــم يقدمــا اعتراضهمــا خــال املــدة‬\n      ‫املقــررة فــإن حقهمــا يف طلــب االعتــراض علــى احلكــم يكــون ســاقط ًا‬\n      ‫وأمــا املدعــي فلكونــه حكــم لــه بجميــع طلبــه وبنــاء علــى املــادة ‪174‬‬\n      ‫مــن نظــام املرافعــات فــا حاجــة لعــرض احلكــم عليــه وللبيــان حــرر يف‬\n      ‫‪1434/03/08‬ه ـ ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                   ‫وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد انتهــت املــدة املقــررة العتــراض املدعــى عليــه‬\n      ‫وذلــك يــوم األربعــاء املوافــق ‪1434/05/15‬ه ـ كمــا انتهــت املــدة املقــررة‬\n\n\n‫‪203‬‬\n\f‫العتــراض املدعــى عليــه وذلــك يــوم االثنــن املوافــق ‪1424/05/27‬ه ـ‬\n‫ولــم يتقدمــا بالئحــة اعتراضيــة علــى احلكــم وبذلــك ســقط حقهمــا يف‬\n‫طلــب االعتــراض علــى احلكــم وســيتم بعــث املعاملــة ملقــام محكمــة‬\n‫االســتئناف لتدقيــق احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/29‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامة مبحافظة األحســاء برقــم ‪331454520‬‬\n‫وتاريــخ ‪1434/6/ 7‬ه ـ واملقيــدة لــدى احملكمــة برقــم ‪341418744‬‬\n‫وتاريــخ ‪1434/6/12‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلة القاضي‬\n‫باحملكمــة الشــيخ‪ /‬املسـ ّـجل برقــم ‪ 34165422‬وتاريــخ ‪1434/3/17‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬ضد‪/‬عــدة غرمــاء يف قضيــة حقوقيــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه‬\n                          ‫حــرر يف ‪1434/6/13‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                                     ‫‪204‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":195,"source_page_end":204,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38627441252a57a8f0d01ca18905d38e2a62ac4b62ac09374f8309fa20f1feb6","normalized_text_hash":"f64561754b37001c1e13f70f1a723c47e9d08826456cb3d3aedab9840c773045","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p195-34165422"},{"id":"92c9068b-4a0b-54ce-bd25-7bde4e38b007","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي إثبات اإلعسار -عدم مصادقة املدعى عليه على إعسار املدعي -عجز املدعى عليه عن إحضار بينة بعدم إعسار املدعي -شهادة الشهود العدول على إعسار املدعي -بقاء مدعي اإلعسار مدة طويلة يف السجن قرينة على صحة دعواه -احلكم بثبوت اإلعسار لثبوت البينة .","document_number":"34176729","case_number":"33691927","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/1","year":"1434","subject":"إعسار -مطالبة املدعي إثبات اإلعسار -عدم مصادقة املدعى عليه على إعسار املدعي -عجز املدعى عليه عن إحضار بينة بعدم إعسار املدعي -شهادة الشهود العدول على إعسار املدعي -بقاء مدعي اإلعسار مدة طويلة يف السجن قرينة على صحة دعواه -احلكم بثبوت اإلعسار لثبوت البينة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/1 :‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176729 :‬‬\n                         ‫َر ْق ُم الدعوى‪33691927 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34230734‬تاريخه‪1434/4/5 :‬هـ‬\n\n\n      ‫إعســار‪ -‬مطالبــة املدعــي إثبــات اإلعســار‪ -‬عــدم مصادقــة املدعــى عليــه‬\n      ‫علــى إعســار املدعــي‪ -‬عجــز املدعــى عليــه عــن إحضــار بينــة بعــدم إعســار‬\n      ‫املدعــي‪ -‬شــهادة الشــهود العــدول علــى إعســار املدعــي‪ -‬بقــاء مدعــي‬\n      ‫اإلعســار مــدة طويلــة يف الســجن قرينــة علــى صحــة دعــواه‪ -‬احلكــم‬\n                                                 ‫بثبــوت اإلعســار لثبــوت البينــة ‪.‬‬\n\n\n\n\n      ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                             ‫ك َ‬   ‫‪ -1‬قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                           ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                        ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n      ‫‪-2‬حديــث قبيصــة بــن املخــارق وفيــه أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال ((حتــى يشــهد ثالثــة مــن ذوي احلجــا أن فالن ـ ًا أصابتــه فاقــة))‬\n\n\n\n\n      ‫ادعــى املدعــي أن يف ذمتــه للمدعــى عليــه مبلغ ـ ًا وقــدره ســتة وســبعون‬\n      ‫ألــف ريــال حيــث كان يعمــل لــدى املدعــى عليه يف محــل أعالف وحصل‬\n      ‫لديــه عجــز يف احملــل وقــد حكــم عليــه بتســليم هــذا املبلــغ مبوجــب‬\n      ‫حكــم صــادر مــن احملكمــة وقــرر املدعــي أنــه معســر وال يســتطيع‬\n      ‫الســداد وطلــب أثبــات إعســاره‪ ،‬أنكــر املدعــى عليــه إعســار املدعــي و‬\n      ‫قــرر أنــه ملــيء ولــم يســتطع إحضــار بينتــه علــى مالئــة املدعــي‪ ،‬أحضــر‬\n\n‫‪205‬‬\n\f‫املدعــي ثالثــة شــهود وجــرى تعديلهــم شــرع ًا شــهدوا علــى صحــة دعــواه‪،‬‬\n‫قــرر ناظــر القضيــة أنــه نظــر ًا الن املدعــي طــال ســجنه ولألســباب‬\n‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة‬ ‫ك َ‬   ‫{و ِإنْ َ‬   ‫املذكــورة ولقولــه تعالــى‪َ :‬‬\n‫ـون} فقــد ثبــت إعســار املدعــي‬                       ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                                                 ‫َكـ ْـم ِإنْ ُ‬\n                                                                                             ‫َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n‫وبــه حكم‪،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة‬\n              ‫االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف املســاعد برقــم ‪ 33691927‬وتاريــخ ‪1433/12/20‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331408177‬وتاريــخ ‪1433/07/27‬ه ـ ففــي‬\n‫يــوم االثنــن املوافق‪1433/12/20‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 00‬‬\n‫وفيهــا حضــر ‪ ........‬ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬كمــا‬\n‫حضــر حلضــوره ‪ ........‬ســعودي اجلنســية يحمــل ســجل مدنــي رقــم ‪........‬‬\n‫وأدعــى قائــا يف دعــواه لقــد كنــت أعمــل يف محــل أعــاف للمدعــى‬\n‫عليــه وقــد حصــل عجــز يف احملــل وهــو مبلــغ وقــدره ســته وســبعون ألــف‬\n‫ريــال وقــد حكــم علــي بذلــك مبوجــب صــك احلكــم الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 11/12/21‬يف ‪1430/2/15‬ه ـ وحيــث أنــي معســر‬\n‫ال أســتطيع ســداد املدعــى عليــه اطلــب إثبــات إعســاري هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكره املدعــي غير صحيح‬\n‫والصحيــح أن لديــه أمــوال منقولــة وهــي عبــارة عــن ثالث ســيارات األولى‬\n‫‪ ........‬والثانيــة والثالثــة ‪ ........‬وقــد حضــر عنــدي مجموعــة مــن أقاربــه‬\n                                                                                                                                      ‫‪206‬‬\n\f      ‫وقالــوا نريــد اعطــاءه مهلــة لكــي يقــوم بتســديد املبلــغ الــذي يف ذمتــه‬\n      ‫وأصلحــوا بينــي وبينــه علــى أن يعطينــي ثالثــة آالف ريــال شــهريا مت دفــع‬\n      ‫قســط واحــد وبعدهــا اختفــى ملــدة خمســة أشــهر تقريبــا وأنــا أعــرف بــأن‬\n      ‫لديــه أمــوال وهــو غيــر معســر هكــذا أجــاب وبعــرض ذلــك علــى املدعــي‬\n      ‫قــال مــا ذكــره املدعــى عليــه غيــر صحيــح والصحيــح مــا ذكرتــه ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه هــل لديــه بينــة علــى مــا ذكــره فقــال أطلــب‬\n      ‫مهلــة إلحضارهــا فأجيــب لطلبــه و يف جلســة أخــرى حضــر فيهــا املدعــي‬\n      ‫و املدعــى عليــه وبســؤال املدعــى عليــه عــن البينــة التــي وعــد بإحضارهــا‬\n      ‫يف اجللســة املاضيــة قــال لــم اســتطع إحضارهــا يف هــذه اجللســة واطلــب‬\n      ‫مهلــة أخــرى إلحضارهــا وبســؤاله عــن املهلــة التــي يرغــب فيهــا فقــال بأنه‬\n      ‫يرغــب يف إمهالــه أربعــة أشــهر هكــذا قــال وحيــث أنــه قــد جــرى إمهــال‬\n      ‫املدعــى عليــه مــدة كافيــة إلحضــار بينتــه وحيــث أن املدعــي ســجني‬\n      ‫وهــو متضــرر مــن كثــرة االســتمهاالت لــذا فقــد جــرى ســؤال املدعــي‬\n      ‫هــل لديــه بينــة علــى أنــه معســر فقــال نعــم واطلــب إمهالــي إلحضــار‬\n      ‫البينــة فأجيــب لطلبــه ويف جلســة أخــرى حضــر فيهــا املدعــي ولــم يحضــر‬\n      ‫املدعــى عليــه وبســؤال املدعــي عــن بينتــه قــال لقــد أحضــرت للشــهادة‬\n      ‫وأدائهــا كال مــن ‪ ........‬ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪........‬‬\n      ‫و‪ .........‬ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬ســوداني اجلنســية‬\n      ‫ا‬\n      ‫مبوجــب اإلقامــة رقــم ‪ ........‬ثــم شــهد كل واحــد منهــم مبفــرده قائ ـ ً‬\n      ‫أشــهد هلل تعالــى أن املدعــي هــذا احلاضــر معســر يف الوقــت احلاضــر‬\n      ‫وال نعلــم لــه أمــواال ثابتــة أو منقولــة هنــا يف الســعودية أو يف الســودان‬\n      ‫هكــذا شــهدوا وقــد جــرى تعديلهــم التعديــل الشــرعي مــن قبــل ‪........‬‬\n      ‫ســوداني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬و ‪ ........‬ســوداني اجلنســية‬\n\n\n‫‪207‬‬\n\f‫مبوجــب اإلقامــة رقــم ‪ ........‬ويف جلســة أخــرى حضــر فيهــا املدعــي ولــم‬\n‫يحضــر املدعــى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن‬\n‫املدعــى عليــه عجــز عــن إحضــار البينــة التــي تثبــت مــا دفــع بــه وإلحضــار‬\n‫املدعــي ثالثــة شــهود وقــد جــرى تعديلهــم شــرع ًا وقــد شــهدوا بإعســار‬\n‫املدعــي وحلديــث قبيصــة بــن احملــارق وفيــه أن النبــي صلــى اهلل عليــه‬\n‫وســلم قــال (حتــى يشــهد ثالثــة مــن ذوي احلجــا أن فالن ـ ًا أصابتــه فاقــه)‬\n‫وبنــاء علــى مــا جــاء يف أوراق املعاملــة وألن بقــاء املدعــي يف الســجن ال‬\n‫يكــون إال إذا ظهــر بأنــه قــادر علــى الســداد و مماطــل ألصحــاب احلــق‬\n‫ومبــا أنــه قــد بقــي يف الســجن مــدة طويلــة لذلــك كلــه فقــد ثبــت لــدي‬\n‫إعســار املدعــي وللمدعــى عليــه مطالبتــه باحلــق متــى مــا أصبــح املدعــي‬\n‫موســر ًا لقولــه تعالــى {وإن كان ذو عســرة فنظــرة إلــى ميســرة} جلميــع‬\n‫مــا تقــدم فقــد حكمــت بإعســار املدعــي وبعــرض احلكــم علــى املدعــي‬\n‫قــرر القناعــة بــه وســيتم بعــث نســخة مــن صــك احلكــم للمدعــى عليــه‬\n‫لتقــدمي مــا لديــه خــال ثالثــن يومـ ًا مــن تاريــخ اســتالمه لنســخة احلكــم‬\n‫وإذا لــم يتقــدم مبــا لديــه فــإن حقــه يف االعتــراض يســقط ويكتســب‬\n‫احلكــم الصفــة القطعيــة واهلل املوفــق وصلــى اهلل عليــه وســلم علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/3/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحد املوافــق ‪ 1434/06/25‬هـ‬\n‫افتتحت اجللســة يف متام الســاعة الثامنة وقد عادت املعاملة من محكمة‬\n‫االســتئناف بخطــاب رئيســها رقــم ‪ 331408177‬يف ‪1434/6/13‬ه ـ‬\n‫واملرفــق بــه قــرار التصديــق للدائــرة احلقوقيــة الرابعــة رقــم ‪34230734‬‬\n‫يف ‪1434/6/5‬ه ـ واملتضمــن وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بإثبــات إعســار املدعــي أ‪.‬ه ـ‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫لــذا فقــد أمــرت بالتهميــش علــى ســجله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/25‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ /‬القاضــي باحملكمــة العامة واملســجل بعــدد ‪34176729‬وتاريخ‬\n      ‫‪1434/4/1‬ه ـ املتضمــن دعــوى ‪ ........‬ســوداني اجلنســية ضــد ‪........‬‬\n      ‫واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم بإثبــات إعســار‬\n          ‫املدعــي‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪209‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":205,"source_page_end":209,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8f95b302cadbb753a0d9281e1449f23fc72edc68c772659d7fb0e2672578e43","normalized_text_hash":"33d4762431bd54f41fb8eef9bdc04bf1073f846c58548a82e20503cb122bf5bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p205-34176729"},{"id":"0633d599-4dcd-5f4b-acc6-8ccce86464df","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وإلزام املدعى عليه إنظار املدعي حلن ميسرة .","document_number":"34191872","case_number":"33428499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة األحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/4/20","year":"1434","subject":"إعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وإلزام املدعى عليه إنظار املدعي حلن ميسرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1432/4/20 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34191872 :‬‬\n                    ‫َر ْق ُم الدعوى‪33428499 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n     ‫‪/34239509‬ق‪/2‬أ تاريخه‪1434/6/13 :‬هـ‬\n\n\n ‫إعســار ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى ســوى اإلعســار‪ -‬التحري‬\n ‫وثبــوت اإلعســار ‪ -‬شــهادة الشــهود بإعســار املدعــي‪ -‬احلكــم بإثبــات‬\n           ‫اإلعســار وإلــزام املدعــى عليــه إنظــار املدعــي حلــن ميســرة ‪.‬‬\n\n\n\n\n ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                        ‫ك َ‬     ‫قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                  ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                               ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليــه وكالــة عــن إحــدى الشــركات بــأن‬\n ‫للشــركة موكلــة املدعــى عليــه يف ذمــة املدعــي مبلغ ـ ًا وقــدره واحــد‬\n ‫وثالثــون ألف ـ ًا ومائتــان وســبعة عشــر ريــا ًال مبوجــب قــرار صــادر مــن‬\n ‫وزارة التجــارة وكذلــك مبلغـ ًا وقــدره عشــرون ألفـ ًا ومائــة وأربعــون ريــا ًال‬\n ‫مبوجــب قــرار أيض ـ ًا مــن وزارة التجــارة «مكتــب الفصــل يف منازعــات‬\n ‫األوراق التجاريــة» وأن املدعــي ال يســتطيع الســداد لكونــه معســر ًا‬\n ‫وطالــب املدعــي إثبــات إعســاره‪ ،‬قــرر املدعــى عليــه وكالة أن الشــركة‬\n ‫تطالــب بحقهــا وال تعلــم عــن إعســار املدعــي ثــم قــرر املدعــى عليــه‬\n ‫وكالــة أن املبلــغ األول مت ســداده مــن فاعــل خيــر وبقــي املبلــغ الثانــي‪،‬‬\n ‫مت البحــث والتحــري عــن مــال املدعــي فلــم يظهــر مــا ًال ميكــن الســداد‬\n                                                                                                                                            ‫‪210‬‬\n\f      ‫منــه‪ ،‬أحضــر املدعــي ثالثــة شــهود يشــهدون علــى صحــة الدعــوى ومت‬\n      ‫تعديلهــم شــرعاً‪ ،‬لألســباب املرصــودة يف نــص احلكــم ولقولــه تعالــى‬\n       ‫َكـ ْـم ِإنْ‬\n                 ‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬ ‫ك َ‬   ‫{و ِإنْ َ‬   ‫َ‬\n      ‫ـون } صــدر احلكــم بثبــوت دعــوى اإلعســار وإلزام الشــركة‬                                               ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬ ‫ُ‬\n      ‫بإنظــار املدعــي إلــى ميســرة‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر‬\n                                   ‫قــرار محكمــة االســتئناف باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫العامــة‬\n          ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫باألحســاء حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬كما حضر املدعى عليه وكالة ‪ ........‬الســعودي بالســجل املدني‬\n      ‫رقــم ‪...........‬بصفتــه وكيــا عــن ‪ ........‬الســعودي مبوجــب الســجل املدني‬\n      ‫رقــم ‪ ........‬بصفتــه رئيــس مجلــس املديريــن لشــركة ‪...........‬للســيارات‬\n      ‫احملــدودة مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال‬\n      ‫محافظــة جــدة برقــم ‪ ...........‬يف ‪1430/11/15‬ه ـ وقــال املدعــي يف‬\n      ‫حتريــر دعــواه إنــه صــدر علــي قــرار مــن وزارة التجــارة مــن مكتــب‬\n      ‫الفصــل يف منازعــات األوراق التجاريــة باألحســاء برقــم‪1431/236‬يف‬\n      ‫‪1431/7/15‬ه ـ بإلزامــي بدفــع واحــد وثالثــن ألــف ومئتــن وســبعة‬\n      ‫عشــر ريــاال للشــركة موكلــة املدعــى عليــه وليــس عنــدي مــا أســدد بــه‬\n      ‫هــذا املبلــغ مــن مــال منقــول أو ثابــت وأنــا معســر وأطلــب إثبــات إعســاري‬\n      ‫هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال إن الشــركة‬\n      ‫موكلتــي تطالــب املدعــي بحقهــا الثابــت وال تعلــم عــن حــال املدعــي‬\n      ‫شــيء كمــا أنــه صــدر عليــه قــرار آخــر مــن وزارة التجــارة بإلزامــه‬\n\n‫‪211‬‬\n\f‫بدفــع عشــرون ألــف ومائــة وأربعــون ريــاال ثابتــة مبوجــب قــرار مكتــب‬\n‫الفصــل يف منازاعــات األوراق التجاريــة رقــم ‪ 33/210‬يف ‪1433/7/6‬ه ـ‬\n‫وبعــرض ذلــك علــى املدعــي قــال صحيــح أنــه صــدر علــي القــرار الــذي‬\n‫ذكــره املدعــى عليــه وكالــة وال أســتطيع تســديد مــا يف ذمتي للشــركة‬\n‫وقــد جــرى منــا مخاطبــة اجلهــات املختصــة ووردنــا إفــادة مؤسســة النقــد‬\n‫العربــي الســعودي بالدمــام رقــم ‪...........‬يف ‪1433/8/19‬ه ـ املتضمــن‬\n‫عــدم وجــود أرصــدة يف حســابات املدعــي كمــا وردنــا إفــادة هيئــة‬\n‫ســوق املــال رقــم ‪...........‬يف ‪1433/7/19‬ه ـ بعــدم وجــود أســهم للمدعــي‬\n‫كمــا وردة إفــادة أمانــة األحســاء رقــم ‪...........‬يف ‪1433/7/19‬ه ـ بعــدم‬\n‫وجــود تصاريــح جتاريــة أو أمــاك عقاريــة للمدعــي ووردتنــا إفــادة‬\n‫غرفــة األحســاء رقــم ‪......................‬يف ‪2012/5/30‬م بعــدم وجــود‬\n‫ســجالت أو اشــتراك للمدعــي لدينــا وإفــادة الزراعــة كذلــك رقــم‬\n‫‪...........‬يف ‪1433/7/2‬ه ـ وإفــادة املــرور األحســاء رقــم ‪2/3/9107/7‬‬\n‫يف ‪1433/7/5‬ه ـ بعــدم وجــود ســيارات حتــت ملكيــة املدعــي ويف‬\n‫جلســة أخــرى قــال املدعــي إننــي قــد مت إطــاق ســراحي حيــث ســدد‬\n‫عنــي فاعــل خيــر هــذا املبلــغ الــذي يف ذمتــي وبعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة قــال إن الشــركة موكلتــي لــم تســتلم شــيء مــن املدعــي‬\n‫وال مــن فاعــل اخليــر الــذي ذكــر كمــا أنــه قــد صــدر علــى املدعــي‬\n‫حكــم آخــر بإلزامــه بدفــع عشــرين ألــف ومائــة وأربعــن ريــاال برقــم‬\n‫‪1433/210‬ه ـ يف ‪1433/7/6‬ه ـ صــادر مــن وزارة التجارة باألحســاء من‬\n‫مكتــب الفصــل يف املنازعــات التجاريــة والشــركة موكلتــي تطالــب‬\n‫املدعــي بهــذا املبلــغ كذلــك إضافــة إلــى املبلــغ الســابق وقــد مت إضافــة‬\n‫هــذه املعاملــة إلــى املعاملــة الســابقة وبعــرض ذلــك علــى املدعــي قــال إن‬\n\n\n                                                                                    ‫‪212‬‬\n\f      ‫القــرار الــذي ذكــر قــد صــدر علــي ولكنــي قــد ســددت للشــركة‬\n      ‫املدعــى عليهــا وســأحضر كشــف حســاب بهــا يف اجللســة القادمــة ويف‬\n      ‫جلســة أخــرى حضــر املدعــي كمــا حضــر املدعــى عليــه وكالــة ‪.......‬‬\n      ‫بعــد انتهــاء اجللســة وقدمــا اعتذارهمــا وقــال املدعــى عليــه وكالــة إن‬\n      ‫الشــركة موكلتــي اســتلمت مــن املدعــي الثابــت يف ذمتــه مــن قــرار‬\n      ‫وزارة التجــارة األول رقــم ‪...........‬يف ‪1431/7/15‬ه ـ والــذي ميثــل مبلــغ‬\n      ‫وقــدره واحــد وثالثــون ألــف ومائتــان وســبعة عشــر ريــاال مت دفعهــا مــن‬\n      ‫قبــل فاعــل خيــر وتبقــى يف ذمــة املدعــي للشــركة موكلتــي عشــرون‬\n      ‫ألــف ومائــة وأربعــون ريــاال وال زالــت الشــركة موكلتــي تطالــب‬\n      ‫بهــذا املبلــغ وقــال املدعــي إن هــذا املبلــغ ال زال يف ذمتــي وال أســتطيع‬\n      ‫تســديده وأطلــب إثبــات إعســاري وطلبــت مــن املدعــي البينــة علــى دعــواه‬\n      ‫و أحضــر كل مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ........‬و‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ........‬و‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وشــهد كل واحــد‬\n      ‫منهــم مبفــرده قائــا أشــهد أن املدعــي معــروف لــي معرفــة تامــة و هــو‬\n      ‫معســر وليــس عنــده مــال ثابــت أو منقــول و ال يســتطيع ســداد مــا يف ذمتــه‬\n      ‫هــذا مــا أشــهد بــه و جــرى عــرض الشــهود و شــهادتهم علــى املدعــى عليــه‬\n      ‫وقــال إنــي ال أعرفهــم و ال مــا ذكــروا يف شــهادتهم و طلبــت مــن املدعــي‬\n      ‫تعديــل بينتــه و أحضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫شــهدا بعدالــة الشــهود وصالحيتهــم للشــهادة فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى و اإلجابــة و بعــد االســتظهار مــن حــال املدعــي و إفــادة اجلهــات‬\n      ‫املختصــة و بنــاء علــى شــهادة الشــهود املعدلــة شــرعا فقــد ثبــت لــدي‬\n\n\n‫‪213‬‬\n\f‫إعســار املدعــي مبــا عليــه مــن ديــن للشــركة املدعــى عليهــا و أنــه يلزمهــا‬\n‫إمهالــه إلــى ميســرة لقولــه تعالــى ( و إن كان ذو عســرة فنظــرة إلــى‬\n‫ميســرة ) اآليــة و بذلــك حكمــت و قــرر املدعــى عليــه وكالــة عــدم‬\n‫قناعتــه و طلــب االســتئناف و أفهمتــه املراجعــة يف يــوم الســبت املوافــق‬\n‫‪1434/04/20‬ه ـ الســتالم نســخة احلكــم و االعتــراض عليــه خــال‬\n‫ثالثــن يومــا و إال ســقط حقــه يف االعتــراض و أصبــح احلكــم قطعيــا‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم ‪ .‬حــرر يف ‪1434/04/15‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/6/25‬ه ـ وقــد وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫الصــادر مــن الدائــرة احلقوقيــة الثانيــة برقــم ‪ / 34239509‬ق ‪ / 2‬أ‬\n‫وتاريــخ ‪1434/6/13‬ه ـ املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪0‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم‪ 341125821‬وتاريــخ ‪ 1434/5/7‬ه ـ الــواردة مــن‬\n‫فضيلة رئيس احملكمة العامة مبحافظة األحســاء برقم ‪331203997‬‬\n‫وتاريــخ ‪1434/ 5/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 34191872‬وتاريــخ ‪1434/4/20‬هـ‬\n‫بشــأن دعــوى‪ /‬ضد‪/‬شــركة ‪ ...........‬للســيارات يف قضيــة حقوقيــة وقــد‬\n‫تضمــن الصــك حكــم فضيلــة القاضــي مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n\n\n                                                                                       ‫‪214‬‬\n\f      ‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                    ‫وآلــه وصحبــه وســلم حــرر يف‪1434/6/13‬ه ـ ‪.‬‬\n\n\n\n\n‫‪215‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":210,"source_page_end":215,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"eb99da041abee0830bf3195694d1b56150df82cbcd24dca5f9bbd94ff399798a","normalized_text_hash":"50c67ea2eb755e9bad6682c21e86ae2bbd03c845d752eca294e6d570bd6b1030","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p210-34191872"},{"id":"fe9d5743-d439-52d3-b99c-f5a1d43a958f","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وعلى املدعى عليه إنظار املدعي حلن ميسرة .","document_number":"34229326","case_number":"33586013","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد بحائل بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود بإعسار املدعي -احلكم بإثبات اإلعسار وعلى املدعى عليه إنظار املدعي حلن ميسرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/4 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34229326 :‬‬\n                   ‫َر ْق ُم الدعوى‪33586013 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34239008‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬مصادقــة املدعــى عليــه علــى‬\n‫الدعــوى ســوى اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود‬\n‫بإعســار املدعــي‪ -‬احلكــم بإثبــات اإلعســار وعلــى املدعــى عليــه إنظــار‬\n                                                   ‫املدعــي حلــن ميســرة ‪.‬‬\n\n\n\n\n‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                       ‫ك َ‬     ‫قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                 ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                              ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n‫ادعــى املدعــي بــأن يف ذمتــه للمدعــى عليــه مبلغ ـ ًا وقــدره مائــة وأربعــون‬\n‫ألــف ريــال ثابتــة مبوجــب صــك شــرعي وأنــه ســجني بســبب هــذا املبلــغ‬\n‫منــذ ثمانيــة أشــهر وقــرر املدعــي أنــه فقيــر ومعســر وال يســتطيع ســداد‬\n‫املبلــغ الــذي يف ذمتــه وطلــب إثبــات إعســاره‪ ،‬رد املدعــى عليــه بعدم علمه‬\n‫بإعســار املدعــي‪ ،‬مت البحــث والتحــري عــن أمــوال مدعــي اإلعســار فلــم‬\n‫يظهــر لناظــر القضيــة وجــود مــال ميكــن منــه ســداد املبلــغ الــذي يف ذمــة‬\n‫املدعــي‪ ،‬أحضــر املدعــي ثالثــة شــهود جــرى تعديلهــم شــهدوا بصحــة‬\n‫ان‬\n‫ك َ‬        ‫{و ِإنْ َ‬\n                  ‫دعــواه‪ ،‬لألســباب املرصــودة يف نــص القضيــة ولقولــه تعالــى َ‬\n‫ك ْن ُتـ ْـم‬‫َكـ ْـم ِإنْ ُ‬\n                        ‫ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n\n                                                                                                                                           ‫‪216‬‬\n\f      ‫ـون } أثبــت ناظــر القضيــة إعســار املدعــي وأن علــى املدعــى عليــه‬\n                                                                            ‫َت ْعل َُمـ َ‬\n      ‫إنظــاره إلــى حــن ميســرة‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬مت تصديــق‬\n                                             ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد واهلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1433/9/24‬ه ـ‬\n      ‫الســاعة احلاديــة عشــر صباحــا لــدي أنــا ‪ ........‬رئيــس احملكمــة العامــة‬\n      ‫املســاعد بحائــل بنــاء علــى املعاملــة احملالــة لنــا برقــم ‪33586013‬‬\n      ‫واملقيــدة باحملكمــة برقــم ‪ 331742312‬وتاريــخ ‪1433/09/23‬ه ـ علــى‬\n      ‫خطــاب مديــر إدارة تنفيــذ األحــكام احلقوقيــة بحائــل رقــم ‪........‬يف‬\n      ‫‪1433/9/23‬ه ـ ألخــذ التوجيــه منــا بشــأن ســجن املدعــو ‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬اســتظهار ًا حلالــه حيــث‬\n      ‫قــرر عــدم اســتطاعته تنفيــذ احلكــم الصــادر منــا برقــم ‪33366623‬‬\n      ‫يف ‪1433/8/4‬ه ـ املتضمــن احلكــم عليــه بتســليم مبلــغ وقــدره مائــة‬\n      ‫وأربعــون ألــف ري ــ‪ 140.000‬ـ ــال وذلــك بحجــة أنــه معســر وحيــث األمــر‬\n      ‫مــا ذكــر وبنــاء علــى الفقــرة (‪ )11‬مــن املــادة (‪ )231‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة ومــا حلقهــا مــن تعديــل مبوجــب قــرار معالــي‬\n      ‫الوزيــر رقــم ‪ 3285‬يف ‪1428/3/15‬ه ـ واملعمــم علــى احملاكــم برقــم‬\n      ‫‪/13‬ت‪ 3093/‬يف ‪1423/4/7‬ه ـ فقــد قــررت ســجن املذكــور أربعــه‬\n      ‫أشــهر اســتظهار ًا حلالــه قبــل عرضــه علينــا وأقفلــت اجللســة يف متــام‬\n      ‫الســاعة احلاديــة عشــر والربــع مــن نفــس اليــوم وبــاهلل التوفيــق وصلــى‬\n                        ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1433/9/24‬ه ـ‬\n      ‫احلمــد واهلل وحــده وبعــد ففــي هــذا اليــوم االثنني املوافــق ‪1434/1/19‬هـ‬\n\n‫‪217‬‬\n\f‫الســاعة الواحــدة ظهــر ًا لــدي أنــا ‪ .........‬مســاعد رئيــس احملكمــة العامــة‬\n‫بحائــل بنــاء علــى املعاملــة املقيــدة بهــذه احملكمــة برقــم ‪ 3447185‬يف‬\n‫‪1434/1/6‬ه ـ علــى خطــاب مديــر إدارة تنفيــذ األحــكام احلقوقيــة‬\n‫بحائــل رقــم ‪........‬يف ‪1434/1/5‬ه ـ ألخــذ التوجيــه منــا بشــأن ســجن‬\n‫مدعــى اإلعســار املدعــو ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬اســتظهار ًا حلالــه حيــث قــرر عــدم اســتطاعته تنفيــذ احلكــم‬\n‫الصــادر منــا برقــم ‪ 33366623‬يف ‪1433/8/4‬ه ـ املتضمــن احلكم عليه‬\n‫بتســليم مبلــغ وقــدره مائــة وأربعــون ألــف ري ــ‪ 140.000‬ـ ــال وذلــك بحجــة‬\n‫أنــه معســر وحيــث األمــر مــا ذكــر وبنــاء علــى الفقــرة (‪ )11‬مــن املــادة‬\n‫(‪ )231‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ومــا حلقهــا‬\n‫مــن تعديــل مبوجــب قــرار معالــي الوزيــر رقــم ‪ 3285‬يف ‪1428/3/15‬ه ـ‬\n‫واملعمــم علــى احملاكــم برقــم ‪/13‬ت‪ 3093/‬يف ‪1423/4/7‬ه ـ فقــد‬\n‫قــررت متديــد ســجن املذكــور شــهر واحــد اســتظهار ًا حلالــه قبــل عرضــه‬\n‫علينــا وأقفلــت اجللســة يف متــام الســاعة الواحــدة والنصــف ظهــر ًا مــن‬\n‫نفــس اليــوم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                                 ‫‪1434/1/19‬هــ‪.‬‬\n‫احلمد واهلل وحده وبعد ففي هذا اليوم األربعاء املوافق ‪1434/2/13‬هـ‬\n‫الســاعة التاســعة لــدي أنــا‪ ................‬مســاعد رئيــس احملكمــة العامــة‬\n‫بحائــل بنــاء علــى املعاملــة املقيــدة بهــذه احملكمــة برقــم ‪ 34355937‬يف‬\n‫‪1434/02/11‬ه ـ علــى خطــاب مديــر إدارة تنفيــذ األحــكام احلقوقيــة‬\n‫بحائــل رقــم ‪ ................‬يف ‪1434/02/11‬ه ـ ألخــذ التوجيــه منــا بشــأن‬\n‫ســجن مدعــى اإلعســار املدعــو ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬اســتظهار ًا حلالــه حيــث قــرر عــدم اســتطاعته تنفيــذ‬\n\n\n                                                                                      ‫‪218‬‬\n\f      ‫احلكــم الصــادر منــا برقــم ‪ 33366623‬يف ‪1433/8/4‬ه ـ املتضمــن‬\n      ‫احلكــم عليــه بتســليم مبلــغ وقــدره مائــة وأربعــون ألــف ري ــ‪ 140.000‬ـ ــال‬\n      ‫وذلــك بحجــة أنــه معســر وحيــث األمــر مــا ذكــر وبنــاء علــى الفقــرة‬\n      ‫(‪ )11‬مــن املــادة (‪ )231‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n      ‫التنفيذيــة ومــا حلقهــا مــن تعديــل مبوجــب قــرار معالــي الوزيــر رقــم‬\n      ‫‪ 3285‬يف ‪1428/3/15‬ه ـ واملعمــم علــى احملاكــم برقــم ‪/13‬ت‪3093/‬‬\n      ‫يف ‪1423/4/7‬ه ـ فقــد قــررت متديــد ســجن املذكــور شــهر واحــد‬\n      ‫اســتظهار ًا حلالــه قبــل عرضــه علينــا وأقفلــت اجللســة يف متــام الســاعة‬\n      ‫الواحــدة والنصــف ظهــر ًا مــن نفــس اليــوم وبــاهلل التوفيــق وصلــى اهلل‬\n                                ‫وســلم علــى نبينــا محمــد حــرر يف ‪1434/1/19‬هــ‪.‬‬\n      ‫احلمــد اهلل وحــده وبعــد ففــي هــذا اليوم االثنني املوافــق ‪1434/05/27‬هـ‬\n      ‫الســاعة العاشــرة صباح ـ ًا افتتحــت اجللســة الرابعــة وفيهــا حضــر ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى علــى‬\n      ‫احلاضــر معــه ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫ا يف حتريــر دعــواه أن لهــذا احلاضــر أمامكــم لــه بذمتــي مبلــغ‬         ‫قائ ـ ً‬\n      ‫وقــدرة مائــه وأربعــون ألــف ريــال حكــم لــه مبوجــب الصــك الصــادر‬\n      ‫منكــم برقــم ‪ 33366623‬يف ‪1433/8/4‬ه ـ وســجنت مبوجبــه ثمانيــة‬\n      ‫أشــهر وال أزال مســجون ًا حتــى تاريــخ اليــوم علــى ذمــه هــذا املبلــغ وأنــا‬\n      ‫رجــل فقيــر ومعســر وال اســتطيع الســداد اطلــب أثبــات إعســاري هــذه‬\n      ‫دعــواي وبســؤال املدعــي عليــه غــرمي املدعــي أجــاب قائ ـاً‪ :‬مــا ذكــره‬\n      ‫مدعــي اإلعســار مــن أن لــي بذمتــه مبلغ ـ ًا وقــدرة مائــة وأربعــون إلــف‬\n      ‫ريــال وحكــم لــي بالصــك املذكــور وســجن مبوجبــه املــدة املذكــورة‬\n      ‫فهــذا كلــه صحيــح ولكــن ال اعلــم عــن حالــة مدعــي اإلعســار شــيئا‬\n\n\n‫‪219‬‬\n\f‫هكــذا أجــاب وباالطــاع علــى أوراق املعاملــة وجــد بــن طياتهــا خطــاب‬\n‫نائــب محافــظ مؤسســة النقــد العربــي الســعودي رقــم‪ ........‬بتاريــخ‬\n‫‪1433/12/1‬ه ـ املتضمــن انــه مت الكشــف عــن أرصدة مدعي اإلعســار‬\n‫واتضــح انــه يوجــد لــه حســابني فقــط ‪-1‬يف مصــرف ‪ ........‬ورصيــده‬\n‫‪ 315.67‬ريــال وأفــاد املصــرف بوجــود ثالثــة عقــود متويــل باســم املذكــور‬\n‫‪ -2‬مجموعــة ‪ ........‬املاليــة أفــادت بوجــود حســاب جــاري باســم املذكــور‬\n‫أعــاه ورصيــده ‪ 6.37‬ريــال كمــا أفــادت املجموعــة بوجــود مديونيــة‬\n‫علــى املذكــور مبلــغ وقــدرة (‪ )45‬ريــال وهــو مرفــق باملعاملــة لفــه (‪)34‬‬\n‫وبطلــب البينــة مــن مدعــي اإلعســار علــى صحــة دعــواه أحضــر للشــهادة‬\n‫ال مــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬  ‫وادائهــا ك ً‬\n‫‪ ........‬مــن مواليــد ‪1397‬ه ـ ليــس لــه صلــة قرابــة باملدعــي و‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬مــن مواليــد ‪1393‬ه ـ ليــس‬\n‫لــه صلــة قرابــة باملدعــي و‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬مــن مواليــد ‪1382‬ه ـ ليــس لــه صلــة قرابــة باملدعــي‬\n‫وباستشــهادهم شــهد كل واحــد منهــم مبفــردة قائـاً‪ :‬اشــهد اهلل تعالــى‬\n‫بــأن املدعــي رجــل فقيــر ومعســر وليــس لديــه مــا يســدد بــه دينــه ال ثابــت‬\n‫وال منقــول نعــرف ذلــك معرفــة تامــة هكــذا شــهدوا وبعــرض الشــهود‬\n‫ومــا جــاء يف شــهادتهم علــى املدعــي عليــه أجــاب قائ ـاً‪ :‬أمــا الشــهود‬\n‫فــا اقــدح بهــم بشــيء أمــا شــهادتهم فــاهلل أعلــم بصحتهــا هكــذا‬\n‫أجــاب كمــا حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n‫وشــهدا بعدالــة الشــهود وانهمــا يقبــان شــهادتهم لهمــا وعليهمــا فبنــاء‬\n‫علــى مــا ســلف مــن الدعــوى واإلجابــة وشــهادة الشــهود املعدلــن التعديــل‬\n\n\n                                                                                      ‫‪220‬‬\n\f      ‫الشــرعي وحيــث جــرى اســتظهار حــال املدعــي بالســجن والكشــف عــن‬\n      ‫أرصدتــه ولقولــه تعالــى ((وإن كان ذو عســرة فنظــرة إلــى ميســرة))‬\n      ‫لذلــك كلــه ثبــت لــدي أن املدعــي رجــل فقيــر ومعســر وأن علــى غرميــه‬\n      ‫املدعــى عليــه إنظــاره إلــى ميســره وبــه حكمــت وبعرضــه علــى الطرفــن‬\n      ‫قــرر املدعــي القناعــة باحلكــم أمــا املدعــى عليــه فقــرر عــدم القناعــة‬\n      ‫وطلــب رفعــة حملكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه‬\n      ‫لطلبــه وقــرر املدعــي عليــه أنــه لــن يوقــع علــى ضبــط القضيــة بحضــور‬\n      ‫شــهادة كاتبــة وأمــرت برفــع كامــل األوراق حملكمــة االســتئناف‬\n      ‫بحائــل لتدقيــق احلكــم ‪ -‬وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــره‬\n      ‫والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/05/27‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت املوافــق ‪1434/6/24‬ه ـ‬\n      ‫الســاعة التاســعة والربــع صباح ـ ًا وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقصيــم بخطــاب فضيلــة رئيســها رقــم ‪3413469050‬‬\n      ‫يف ‪1434/6/18‬ه ـ املرفــق بــه قــرار أصحــاب ‪ 34239008‬يف‬\n      ‫‪1434/6/12‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة (( وبدراســة الصــك‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة جــرت املصادقــة علــى مــا حكــم بــه‬\n      ‫فضيلتــه واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬قاضــي اســتئناف‪،........‬ختمه وتوقيعــه‪ .‬قاضــي اســتئناف‪،........‬‬\n      ‫ختمــه وتوقيعــه‪ .‬رئيــس الدائــرة‪ ،........‬ختمــه وتوقيعــه )) أ‪.‬ه ـ وعليــه فقــد‬\n      ‫رفعــت اجللســة يف متــام الســاعة التاســعة والنصــف صباحـ ًا يف نفــس اليــوم‬\n              ‫وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬حــرر يف ‪1434/6/24‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n\n\n‫‪221‬‬\n\f‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n‫حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪ 341346905‬وتاريــخ ‪1434/6/4‬ه ـ واملقيــدة‬\n‫لدينــا بتاريــخ ‪1434/6/6‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34229326‬يف‬\n‫‪1434/6/4‬ه ـ الصــادر مــن فضيلــة رئيــس احملكمــة املســاعد اخلــاص‬\n‫بدعــوى ‪ ........‬ضــد ‪ ........‬بشــأن إثبــات إعســار علــى الصفــة املوضحــة يف‬\n‫الصــك واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيه وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة‪ :‬جــرت املصادقــة علــى ماحكــم‬\n‫بــه فضيلتــه واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                       ‫وصحبــه‪.‬‬\n\n\n\n\n                                                                                    ‫‪222‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":216,"source_page_end":222,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c6050b57a953b7e1e527d38337296b0566e525cf6be4d068a32b174dc16eff1f","normalized_text_hash":"eb953ed08c6a316ebb51bb82e72f3427ac7c512853e86973afbb2ab688c2405a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p216-34229326"},{"id":"6467fdf4-ce76-5ba6-9e08-ab5340b692d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدل بإعسار املدعي -احلكم بثبوت اإلعسار .","document_number":"34231347","case_number":"33532463","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/5","year":"1434","subject":"إعسار -مطالبة املدعي بإثبات اإلعسار -مصادقة املدعى عليه على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدل بإعسار املدعي -احلكم بثبوت اإلعسار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/5 :‬هـ‬\n                     ‫ُ‬                  ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34231347 :‬‬\n                         ‫َر ْق ُم الدعوى‪33532463 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34276119‬تاريخه‪1434/7/23 :‬هـ‬\n\n\n      ‫إعســار‪ -‬مطالبــة املدعــي بإثبــات اإلعســار‪ -‬مصادقــة املدعــى عليــه علــى‬\n      ‫الدعــوى ســوى اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود‬\n                              ‫العــدل بإعســار املدعــي‪ -‬احلكــم بثبــوت اإلعســار ‪.‬‬\n\n\n\n\n      ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬\n                                                                                            ‫ك َ‬    ‫‪ .1‬قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                          ‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                       ‫ـون }‬                        ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n      ‫‪ .2‬حديــث قبيصــة بــن املخــارق وفيــه أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال (( إن املســألة ال حتــل إال ألحــد ثالثــة ‪ -‬وذكــر منهــم ‪ -‬ورجــل‬\n      ‫أصابتــه فاقــة حتــى يقــول ثالثــة مــن ذوي احلجــا مــن قومــه لقــد‬\n                                   ‫أصابــت فــان فاقــة فحلــت لــه املســألة )) رواه مســلم‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه صــدر ضــده القــرار الصــادر مــن مكتــب الفصــل‬\n      ‫يف منازعــات األوراق التجاريــة مبكــة املكرمــة يتضمــن أن يســلم‬\n      ‫املدعــي للمدعــى عليــه مبلغــا وقــدره ثالثمائــة ألــف ريــال وقــرر املدعــي‬\n      ‫أنــه معســر وال يســتطيع الســداد وال عمــل لديــه وطلــب إثبــات إعســاره‪،‬‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي ســوى اإلعســار فقــرر عــدم‬\n      ‫علمــه بــه‪ ،‬أحضــر املدعــي ثالثــة شــهود مت تعديلهــم شــرعا يشــهدون‬\n\n‫‪223‬‬\n\f‫علــى صحــة الدعــوى‪ ،‬مت التحــري عــن مــال املدعــي فلــم يظهــر وجــود‬\n‫مــال ميكــن الســداد منــه‪ ،‬لألســباب املرصــودة يف نــص احلكــم ولقولــه‬\n‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر‬  ‫ك َ‬   ‫تعالــى { َو ِإنْ َ‬\n‫ـون } مت إثبــات إعســار املدعــي‪ ،‬قــرر املدعــى عليــه‬                                   ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                                                                                    ‫َكـ ْـم ِإنْ ُ‬\n                                                                                                                                ‫ل ُ‬\n                        ‫عــدم القناعــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم األحــد املوافــق ‪1434/05/05‬ه ـ لــدي‬\n‫أنــا ‪ ........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n‫املعاملــة احملالــة إلينــا بشــرح رئيــس احملكمــة برقــم ‪ 33532463‬وتاريــخ‬\n‫‪1433/08/18‬ه ـ املقيــد بأســاس هــذه احملكمــة برقــم ‪331495597‬‬\n‫وتاريــخ ‪1433/08/10‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة‬\n‫والنصــف صباحـ ًا وقــد جــرى الكتابــة للحقــوق املدنيــة مبوجــب خطابنــا‬\n‫رقــم ‪ 34839114‬وتاريــخ ‪1434/04/10‬ه ـ إلحضــار الســجني ويف هــذه‬\n‫اجللســة حضــر فيهــا ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ........‬وحضر حلضوره ‪ ........‬ســعودي بالســجل املدني رقم ‪ ........‬فادعى‬\n‫ا يف تقريــر دعــواه ‪ :‬لقــد صــدر ضــدي القــرار الصــادر مــن‬    ‫املدعــي قائـ ً‬\n‫مكتــب الفصــل يف منازعــات األوراق التجاريــة مبكــة املكرمــة برقــم‬\n‫‪ ........‬وتاريــخ ‪1432/12/26‬ه ـ للمدعــى عليــه وحيــث أننــي مطالــب‬\n‫للمدعــى عليــه مببلــغ وقــدره (‪ 300000‬ثالثمائــة ألف ريــال ) وحيث أنني‬\n‫معســر وليــس لــدي عمــل وال أملــك أيــة مــال ؛ لــذا أطلــب إثبــات إعســاري‬\n‫هــذه دعــواي ‪ ،‬وبعرضهــا علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره‬\n‫املدعــي يف دعــواه مــن ناحيــة صــدور القــرار ومقــدار املبلــغ فصحيــح ومــا‬\n\n                                                                                                                                      ‫‪224‬‬\n\f      ‫ذكــره مــن إعســاره باملبلــغ وأال عمــل لديــه وأنــه معســر وال ميلــك مــا ًال‬\n      ‫فــا أعلــم عنــه شــيئ ًا وأطلــب إلزامــه بســداد املبلــغ هكــذا أجــاب ثــم‬\n      ‫جــرى اطالعــي علــى القــرار الصــادر مــن مكتــب الفصــل يف منازعــات‬\n      ‫األوراق التجاريــة مبكــة املكرمــة رقــم ‪ ........‬وتاريــخ ‪1432/12/26‬ه ـ‬\n      ‫فــإذا هــو يتضمــن إلــزام املدعــي بســداد مبلــغ وقــدره (‪ 300000‬ثالثمائــة‬\n      ‫ألــف ريــال ) ثــم جــرى اطالعــي علــى إفــادة مؤسســة النقــد العربــي‬\n      ‫الســعودي مبكــة املكرمــة رقــم ‪ ........‬وتاريــخ ‪1433/11/16‬هـ فإذا هو‬\n      ‫يتضمــن لــدى املدعــي فقــط مبلــغ وقــدره (‪ 2958‬ألفــا وتســعمائة وثمــان‬\n      ‫وخمســون ريــال يف البنــك ‪ ) ........‬ثــم جــرى اطالعــي علــى إفــادة أمانــة‬\n      ‫العاصمــة املقدســة رقــم ‪........‬وتاريــخ ‪1433/09/13‬ه ـ فــإذا هــو يتضمــن‬\n      ‫عــدم وجــود رخــص محــات مســجلة باســمه ثــم ســألت املدعــى عليــه هــل‬\n      ‫يعــرف أعيــان مــال للمدعــى عليــه أو عقــار ؟ فأجــاب ‪ :‬ال أعلــم لــه شــيئ ًا‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب ‪ :‬بأننــي معســر وال‬\n      ‫أملــك شــيئ ًا ولــدي البينــة علــى ذلــك هكــذا أجــاب ولذا رفعت اجللســة ثم‬\n      ‫يف يــوم األربعــاء املوافــق ‪1434/05/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫املدعــي واملدعــى عليــه املنــوه عنهمــا بعاليــه ‪ ،‬وبســؤال املدعــي عمــا‬\n      ‫وعــد بــه يف اجللســة املاضيــة مــن إحضــار البينــة علــى أنــه معســر أحضــرا‬\n      ‫للشــهادة كال مــن ‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n      ‫‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ........‬و‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ،........‬وبســؤالهم‬\n      ‫عمــا لديهــم شــهد كل واحــد منهــم مبفــرده قائ ـاً‪ :‬إن املدعــي فقيــر ال‬\n      ‫مــال لــه وهــو محتــاج للمســاعدة ونحــن نعرفــه متــام املعرفــة وهــو عاجــز‬\n      ‫عــن ســداد مــا بذمتــه مــن مبالــغ هكــذا شــهدوا ‪ ،‬وبعــرض الشــهادة‬\n\n\n‫‪225‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":223,"source_page_end":225,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0331596b8046426e6243dd962617846d65e66810881c0febadda98f9ccfe60c6","normalized_text_hash":"e13e0d175c7815ea888a267e130d25259fbbc26018e6ebf4ccb7d226c4b82af4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p223-34231347"},{"id":"045730f8-29cb-5ba1-9a64-05bdd7961910","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة بإثبات إعسار -ثبوت الدين مبوجب سرقة -نصت التعليمات بعدم التساهل يف إثبات إعسار من كان دينه ناشئ عن سرقة ونحوه -احلكم بصرف النظر عن دعوى اإلعسار ألن الدين ثابت مبوجب سرقة واإللزام بدفع املبلغ .","document_number":"34250292","case_number":"33254934","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/25","year":"1434","subject":"إعسار -مطالبة بإثبات إعسار -ثبوت الدين مبوجب سرقة -نصت التعليمات بعدم التساهل يف إثبات إعسار من كان دينه ناشئ عن سرقة ونحوه -احلكم بصرف النظر عن دعوى اإلعسار ألن الدين ثابت مبوجب سرقة واإللزام بدفع املبلغ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34250292 :‬‬\n                         ‫َر ْق ُم الدعوى‪33254934 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34367196‬تاريخه‪1434/11/24 :‬هـ‬\n\n\n      ‫إعســار ‪ -‬مطالبــة بإثبــات إعســار ‪ -‬ثبــوت الديــن مبوجــب ســرقة ‪ -‬نصــت‬\n      ‫التعليمــات بعــدم التســاهل يف إثبــات إعســار مــن كان دينــه ناشــئ عــن‬\n      ‫ســرقة ونحــوه ‪ -‬احلكــم بصــرف النظــر عــن دعــوى اإلعســار ألن الديــن‬\n                                  ‫ثابــت مبوجــب ســرقة واإللــزام بدفــع املبلــغ ‪.‬‬\n\n\n\n\n      ‫تعميمــي معالــي وزيــر العــدل ذي الرقــم ‪/12/136‬ت والتاريــخ ‪1402/10/28‬ه ـ‬\n                                ‫وذي الرقــم ‪/13‬ت‪ 826/‬والتاريــخ ‪1416/07/04‬هــ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي (أجنبــي) يجيــد اللغــة العربية ضد ممثل الشــؤون الصحية‬\n      ‫بأنــه قــد صــدر عليــه حكــم شــرعي بإلزامــه بدفــع مبلــغ قيمــة أدويــة‬\n      ‫لــوزارة الصحــة ثــم ادعــى اإلعســار لــدى فضيلــة مصــدر احلكــم وحكــم‬\n      ‫بإثبــات إعســاره ونقــض احلكــم مــن محكمــة االســتئناف وليــس لديــه‬\n      ‫أمــوال وفقيــر ويطلــب إثبــات إعســاره هكــذا ادعــى‪ ،‬أجــاب املدعــى‬\n      ‫عليــه وكالــة بــأن مــا ذكــره املدعــي فهــو صحيــح ولكــن موكلتــه ال‬\n      ‫توافــق علــى إثبــات إعســاره وال تعلــم هــل لــه أمــوال أم ال وتطلــب احلكــم‬\n      ‫بــرد دعــواه‪ ،‬مت االطــاع علــى الصــك ويتضمــن أن مدعــي اإلعســار‬\n      ‫كان يعمــل فنــي تبريــد بــإدارة التمويــن الطبــي وقــد قــام بعــدة ســرقات‬\n‫‪229‬‬\n\f‫لكراتــن أدويــة وأنــه قــد ألــزم مببلــغ وقــدره (‪ ،)....‬وبنــاء علــى مــا‬\n‫جــاء يف تعميمــي معالــي وزيــر العــدل ذي الرقــم ‪/12/136‬ت والتاريــخ‬\n‫‪1402/10/28‬ه ـ وذي الرقــم ‪/13‬ت‪ 826/‬والتاريــخ ‪1416/07/04‬ه ـ‬\n‫واملتضمنــة عــدم التســاهل يف إثبــات اإلعســار إذا كان ســرقة‪ ،‬وملــا‬\n‫أن املبلــغ كبيــر جــدا‪ ،‬ملــا تقــدم لــم يثبــت أن املدعــي معسـ ّـر واحلكــم‬\n‫بصــرف النظــر عــن دعــواه يف اإلعســار وإلزامــه بدفــع املبلــغ املذكــور‬\n‫أعــاه للمدعــى عليهــا‪ ،‬اعتــرض املدعــي علــى احلكــم بالئحــة‪ ،‬صــدق‬\n          ‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪ 33254934‬وتاريــخ‬\n‫‪1433/04/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33529451‬وتاريــخ‬\n‫‪1433/03/20‬ه ـ ففــي يــوم األربعــاء ‪1434/01/28‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة التاســعة وفيهــا حضــر ‪ ....‬بنجالديشــي اجلنســية مســلم‬\n‫الديانــة مبوجــب رخصــة اإلقامــة رقــم ‪ ....‬كمــا حضــر حلضــوره ‪....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬بصفتــه ممثــل الشــؤون‬\n‫الصحيــة باخلطــاب رقــم ‪/47/110/101‬ج وتاريــخ ‪1434/01/27‬ه ـ‬\n‫الصــادر مــن مديــر الشــؤون الصحيــة مبحافظــة جــدة وادعــى األول‬\n‫قائــا وهــو يجيــد اللغــة العربيــة إنــه قــد صــدر علــي مــن فضيلــة الشــيخ‬\n‫‪ ............‬القاضــي بهــذه احملكمــة حكــم شــرعي بالصــك رقــم‬\n‫‪ 9/ 491/121‬وتاريــخ ‪1422/10/25‬ه ـ واملصــدق مــن الدائــرة احلقوقيــة‬\n\n                                                                                    ‫‪230‬‬\n\f      ‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة واملتضمــن بــأن‬\n      ‫أدفــع مبلغــا وقــدره ‪ 711562,02‬ســبعمائة وأحــد عشــر ألفــا وخمســمائة‬\n      ‫واثنــان وســتون ريــاال وهللتــان قيمــة أدويــة لــوزارة الصحــة ثــم ادعيــت‬\n      ‫اإلعســار لــدى فضيلــة ‪ ....‬وحكــم بإثبــات إعســاري بالصــك رقــم‬\n      ‫‪ 9358371226310154‬وتاريــخ ‪1431/11/18‬ه ـ ونقــض احلكــم‬\n      ‫مــن الدائــرة اجلزائيــة الرابعــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة بالقــرار رقــم ‪ 33122780‬وتاريــخ ‪1433/3/9‬ه ـ واملتضمــن‬\n      ‫نقــض احلكــم باألكثريــة وحتــال القضيــة لقاضــي آخــر للنظــر فيهــا‬\n      ‫مــن جديــد بعــد إنهــاء إجــراءات التهميــش علــى ضبطــه وســجله وأحيلــت‬\n      ‫لفضيلتكــم وإنــه ليــس لــدي أمــوال وإننــي فقيــر أطلــب إثبــات إعســاري‬\n      ‫هكــذا ادعــى وبســؤال املدعــى عليــه وكالــة اإلجابــة أجــاب قائــا مــا‬\n      ‫ذكــره املدعــي فهــو صحيــح ولكــن موكلتــي ال توافــق علــى إثبــات‬\n      ‫إعســاره وال تعلــم هــل لــه أمــوال أم ال وتطلــب احلكــم بــرد دعــواه‬\n      ‫هكــذا أجــاب والنتهــاء وقــت اجللســة رفعــت اجللســة واختتمــت اجللســة‬\n      ‫ثــم يف يــوم األربعــاء املوافق‪1434/02/13‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫الثامنــة والنصــف وفيهــا حضــر املدعــي أصالــة ‪....‬املثبتــة هويتــه ســابقا‬\n      ‫لســماع دعــواه ‪....‬بشــأن دعــوى يف موضــوع حكــم منقــوض ‪ /‬غيــر‬\n      ‫مشــتركة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وقــد مت االطــاع علــى‬\n      ‫الصــك رقــم ‪ 9/491/121‬وتاريــخ ‪1422/01/25‬ه ـ واملصــادق عليــه‬\n      ‫مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة‬\n      ‫املكرمــة بالقــرار رقــم ‪ 1/2/314‬وتاريــخ ‪1423/03/16‬ه ـ ووجدتــه‬\n      ‫يتضمــن أن مدعــي اإلعســار كان يعمــل فنــي تبريــد بــإدارة التمويــن‬\n      ‫الطبــي وقــد قــام بعــدة ســرقات لكراتــن أدويــة وأنــه قــد ألــزم مببلــغ‬\n\n\n‫‪231‬‬\n\f‫وقــدره (‪ )711562,02‬ســبعمائة وأحــد عشــر ألفــا وخمســمائة واثنــان‬\n‫وســتون ريــاال وهللتــان كمــا قــد مت االطــاع على صك احلكــم املنقوض‬\n‫املذكــور يف دعــوى املدعــي فوجدتــه كمــا ذكــر ورفعت اجللســة للتأمل‬\n‫واختتمــت اجللســة ثــم يف يــوم األحــد ‪1434/06/11‬هـ افتتحت اجللســة يف‬\n‫الســاعة الثامنــة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــي أصالــة ‪....‬‬\n‫املثبتــة هويتــه ســابقا كمــا حضــر حلضــوره ‪....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪....‬بصفتــه ممثــل الشــؤون الصحيــة باخلطــاب رقــم‬\n‫‪/47/110/653‬ج وتاريــخ ‪1434/06/04‬ه ـ الصــادر مــن مديــر الشــؤون‬\n‫الصحيــة مبحافظــة جــدة ورفعــت اجللســة للتأمــل واختتمــت اجللســة ثــم‬\n‫يف يــوم األربعاء‪1434/06/21‬ه ـ افتتحــت اجللســة يف الســاعة الثامنــة‬\n‫والنصــف وفيهــا حضــر املدعــي أصالــة ‪....‬املثبتــة هويتــه ســابقا كمــا‬\n‫حضــر حلضــوره ممثــل املدعــى عليهــا ‪....‬املثبتــة هويتــه وتفويضــه ســابقا‬\n‫وقــد مت االطــاع علــى قــرار محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة رقــم ‪ 33122780‬وتاريــخ ‪1433/03/09‬ه ـ واملتضمــن نقــض‬\n‫احلكــم باألكثريــة وحتــال القضيــة لقــاض آخــر للنظــر فيهــا مــن‬\n‫جديــد بعــد إنهــاء إجــراءات التهميــش علــى ضبطــه وســجله ا‪.‬ه ـ فبنــاء‬\n‫علــى مــا تقــدم مــن دعــوى املدعــي واملتضمنــة طلبــه إثبــات إعســاره جهــة‬\n‫املدعــى عليهــا علــى مــا جــاء يف دعــواه وبنــاء علــى إجابــة املدعــى عليهــا‬\n‫واملتضمنــة عــدم املوافقــة علــى إثبــات إعســاره للمدعــي وبنــاء علــى مــا‬\n‫جــاء يف تعميمــي معالــي وزيــر العــدل ذي الرقــم ‪/12/136‬ت والتاريــخ‬\n‫‪1402/10/28‬ه ـ وذي الرقــم ‪/13‬ت‪ 826/‬والتاريــخ ‪1416/07/04‬ه ـ‬\n‫واملتضمنــة عــدم التســاهل يف إثبــات اإلعســار إذا كان ســرقة وملــا‬\n‫أن املبلــغ كبيــر جــدا فلــم يثبــت لــدي أن املدعــي معســرا وعليــه فقــد‬\n\n\n                                                                                      ‫‪232‬‬\n\f      ‫صرفــت النظــر عــن دعــواه يف اإلعســار وألزمتــه بدفــع املبلــغ املذكــور‬\n      ‫أعــاه للمدعــى عليهــا وبــه حكمــت وبإعــان احلكــم علــى املدعــي‬\n      ‫اعتــرض وطلــب التمييــز واســتعد بتقــدمي الئحــة اعتراضيــة فأفهــم بــأن‬\n      ‫عليــه مراجعــة احملكمــة يــوم األحــد ‪1434/06/25‬ه ـ الســتالم نســخة‬\n      ‫احلكــم وإذا فــات علــى ميعــاد االعتــراض ثالثــون يومــا ولــم يقــدم الئحته‬\n      ‫االعتراضيــة ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‪،‬‬\n      ‫واختتمــت اجللســة يف الســاعة التاســعة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/06/21‬ه ـ‬\n      ‫احلمــد هلل وحــده بعــد ففــي يــوم الثالثــاء ‪1434/06/27‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الثانيــة والنصــف وفيهــا حضــر املدعــي أصالــة ‪....‬‬\n      ‫املثبتــة هويتــه ســابقا واســتلم نســخة احلكــم وأفهــم بتعليمــات التمييــز‬\n      ‫كمــا يف اجللســة املاضيــة فتفهــم ذلــك‪ ،‬واختتمــت اجللســة ثــم يف يــوم‬\n      ‫األحــد ‪1434/07/23‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة عشــرة‬\n      ‫وفيهــا حضــر املدعــي أصالــة ‪....‬املثبتــة هويتــه ســابقا وقــدم الئحتــه‬\n      ‫االعتراضيــة املقيــدة يف احملكمــة برقــم ‪ 341775902‬وتاريــخ‬\n      ‫‪1434/07/23‬ه ـ واملكونــة مــن ورقــة واحــدة ورفعــت اجللســة لدراســتها‬\n      ‫واختتمــت اجللســة ثــم يف يــوم الســبت ‪1434/07/29‬ه ـ افتتحــت اجللســة‬\n      ‫يف الســاعة العاشــرة والربــع وقــد مت االطــاع علــى الالئحــة االعتراضيــة‬\n      ‫املقدمــة مــن املدعــي املذكــور رقــم قيدهــا وتاريخــه أعــاه ولــم أجــد بهــا‬\n      ‫مــا يؤثــر علــى مــا حكمــت بــه لــذا قــررت رفعهــا مــع كامــل املعاملــة‬\n      ‫والصــك وصــورة مصدقــة مــن الضبــط بعــد إحلــاق مــا اســتجد علــى‬\n      ‫الصــك والســجل حملكمــة االســتئناف‪ ،‬واختتمــت اجللســة يف الســاعة‬\n      ‫العاشــرة وخمــس وأربعــن دقيقــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n\n\n‫‪233‬‬\n\f   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/29‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬نحــن رئيس وقضاة‬\n‫الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة جــرى منــا االطــاع علــى الصــك رقــم ‪34250292‬وتاريــخ‬\n‫‪1434/6/25‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ ....‬القاضــي باحملكمــة‬\n‫العامــة مبحافظــة جــدة‪ ،‬املتضمــن دعــوى‪ ....‬بنجالديشــي اجلنســية‬\n‫ضــد‪ /‬الشــئون الصحيــة مبحافظــة جــدة‪ ،‬بشــأن طلــب أثبــات إعســار‪،‬‬\n‫احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم‪ ،‬واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪234‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":229,"source_page_end":234,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83f98f86444c3f7ee269f220261bedfa7beff3026985158881fcc17532fad96c","normalized_text_hash":"9b828fde56e78b2597e2f9a44a29031a2307bc4249fdb1889c772878236a0495","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p229-34250292"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
